import type { RawQ } from "../types";
// ʿUlūm al-Qurʾān: compilation, rasm and dotting, order and divisions, naskh, muḥkam/mutashābih, ʿāmm/khāṣṣ, muṭlaq/muqayyad, iʿjāz, major works, history of tafsīr. Draft content, needs scholarly review.
export const QS: RawQ[] = [
  // ---- compilation: the Prophet's time, Abū Bakr, ʿUthmān ----
  { id: "ulc-001", s: "ulum", g: 1, d: 1, t: ["compilation", "abu-bakr-compilation"], src: "al-Bukhārī, Ṣaḥīḥ, Kitāb Faḍāʾil al-Qurʾān, bāb jamʿ al-Qurʾān",
    en: ["Whom did Abū Bakr al-Ṣiddīq charge with collecting the Quran into one compilation?", ["Zayd ibn Thābit", "Ubayy ibn Kaʿb", "ʿAbd Allāh ibn Masʿūd", "Muʿādh ibn Jabal"], "According to the report of Zayd himself in Ṣaḥīḥ al-Bukhārī, Abū Bakr chose Zayd ibn Thābit, who had been a scribe of the revelation for the Prophet. Ubayy, Ibn Masʿūd and Muʿādh were famous reciters, but the task was given to Zayd."],
    de: ["Wen beauftragte Abū Bakr al-Ṣiddīq damit, den Koran in einer Sammlung zusammenzutragen?", ["Zayd ibn Thābit", "Ubayy ibn Kaʿb", "ʿAbd Allāh ibn Masʿūd", "Muʿādh ibn Jabal"], "Nach dem Bericht Zayds selbst im Ṣaḥīḥ al-Bukhārī wählte Abū Bakr Zayd ibn Thābit, der für den Propheten die Offenbarung niedergeschrieben hatte. Ubayy, Ibn Masʿūd und Muʿādh waren berühmte Rezitatoren, doch die Aufgabe erhielt Zayd."],
    ar: ["مَن كلَّفه أبو بكر الصديق بجمع القرآن في موضع واحد؟", ["زيد بن ثابت", "أُبيّ بن كعب", "عبد الله بن مسعود", "معاذ بن جبل"], "في رواية زيد نفسه في صحيح البخاري اختار أبو بكر زيدَ بن ثابت، وكان من كتّاب الوحي للنبي صلى الله عليه وسلم. وكان أُبيّ وابن مسعود ومعاذ من القرّاء المشهورين، لكن المهمة أُسندت إلى زيد."] },

  { id: "ulc-002", s: "ulum", g: 1, d: 1, t: ["compilation", "abu-bakr-compilation"], src: "al-Bukhārī, Ṣaḥīḥ, Kitāb Faḍāʾil al-Qurʾān, bāb jamʿ al-Qurʾān",
    en: ["Which event prompted the compilation of the Quran under Abū Bakr?", ["The death of many reciters at the Battle of al-Yamāma", "The death of many reciters at the Battle of Uḥud", "The death of many reciters at Biʾr Maʿūna", "The death of many reciters at the Battle of Muʾta"], "Many memorisers of the Quran were killed at al-Yamāma, fought against Musaylima after the Prophet's death, and ʿUmar feared that parts of the Quran could be lost. Biʾr Maʿūna and Uḥud were also tragic losses, but they happened during the Prophet's lifetime."],
    de: ["Welches Ereignis gab den Anstoß zur Sammlung des Korans unter Abū Bakr?", ["Der Tod vieler Rezitatoren in der Schlacht von al-Yamāma", "Der Tod vieler Rezitatoren in der Schlacht von Uḥud", "Der Tod vieler Rezitatoren bei Biʾr Maʿūna", "Der Tod vieler Rezitatoren in der Schlacht von Muʾta"], "In al-Yamāma, der Schlacht gegen Musaylima nach dem Tod des Propheten, fielen viele Koranbewahrer, und ʿUmar befürchtete, dass Teile des Korans verloren gehen könnten. Biʾr Maʿūna und Uḥud waren ebenfalls schwere Verluste, fanden aber zu Lebzeiten des Propheten statt."],
    ar: ["ما الحدث الذي دعا إلى جمع القرآن في عهد أبي بكر؟", ["استحرار القتل بالقرّاء يوم اليمامة", "استحرار القتل بالقرّاء يوم أُحد", "استحرار القتل بالقرّاء يوم بئر معونة", "استحرار القتل بالقرّاء يوم مؤتة"], "قُتل كثير من حفّاظ القرآن في معركة اليمامة ضد مسيلمة بعد وفاة النبي صلى الله عليه وسلم، فخشي عمر أن يذهب كثير من القرآن. أما بئر معونة وأُحد فكانتا في حياة النبي صلى الله عليه وسلم."] },

  { id: "ulc-003", s: "ulum", g: 1, d: 2, t: ["compilation", "abu-bakr-compilation"], src: "al-Bukhārī, Ṣaḥīḥ, Kitāb Faḍāʾil al-Qurʾān, bāb jamʿ al-Qurʾān",
    en: ["After the death of ʿUmar, with whom were the sheets (ṣuḥuf) compiled under Abū Bakr kept?", ["Ḥafṣa bint ʿUmar", "ʿĀʾisha bint Abī Bakr", "Zayd ibn Thābit", "ʿUthmān ibn ʿAffān"], "The report in al-Bukhārī states that the sheets stayed with Abū Bakr until his death, then with ʿUmar, then with his daughter Ḥafṣa, the Mother of the Believers. ʿUthmān later borrowed them from her to make his copies."],
    de: ["Bei wem wurden die unter Abū Bakr gesammelten Blätter (ṣuḥuf) nach dem Tod ʿUmars aufbewahrt?", ["Ḥafṣa bint ʿUmar", "ʿĀʾisha bint Abī Bakr", "Zayd ibn Thābit", "ʿUthmān ibn ʿAffān"], "Laut dem Bericht bei al-Bukhārī blieben die Blätter bis zu seinem Tod bei Abū Bakr, dann bei ʿUmar und danach bei dessen Tochter Ḥafṣa, der Mutter der Gläubigen. ʿUthmān lieh sie später von ihr, um seine Abschriften anzufertigen."],
    ar: ["عند مَن حُفظت الصحف التي جُمعت في عهد أبي بكر بعد وفاة عمر؟", ["حفصة بنت عمر", "عائشة بنت أبي بكر", "زيد بن ثابت", "عثمان بن عفان"], "في رواية البخاري أن الصحف كانت عند أبي بكر حتى توفاه الله، ثم عند عمر حياته، ثم عند حفصة بنت عمر أم المؤمنين، ومنها أخذها عثمان لينسخ المصاحف."] },

  { id: "ulc-004", s: "ulum", g: 1, d: 1, t: ["compilation", "uthman-compilation"], src: "al-Bukhārī, Ṣaḥīḥ, Kitāb Faḍāʾil al-Qurʾān, bāb jamʿ al-Qurʾān",
    en: ["Which caliph had standardised copies of the Quran made and sent to the main regions?", ["ʿUthmān ibn ʿAffān", "Abū Bakr al-Ṣiddīq", "ʿUmar ibn al-Khaṭṭāb", "ʿAlī ibn Abī Ṭālib"], "ʿUthmān had copies made from the sheets kept by Ḥafṣa and sent them to the regions so that people would unite on them. Abū Bakr's compilation was a single set of sheets that was not distributed."],
    de: ["Welcher Kalif ließ einheitliche Koranabschriften anfertigen und in die wichtigsten Regionen senden?", ["ʿUthmān ibn ʿAffān", "Abū Bakr al-Ṣiddīq", "ʿUmar ibn al-Khaṭṭāb", "ʿAlī ibn Abī Ṭālib"], "ʿUthmān ließ nach den Blättern Ḥafṣas Abschriften anfertigen und in die Regionen schicken, damit sich die Menschen auf sie einigten. Die Sammlung Abū Bakrs war ein einziger Satz Blätter, der nicht verteilt wurde."],
    ar: ["أيّ الخلفاء نَسخ المصاحف الموحَّدة وأرسلها إلى الأمصار؟", ["عثمان بن عفان", "أبو بكر الصديق", "عمر بن الخطاب", "علي بن أبي طالب"], "نسخ عثمان المصاحف من الصحف التي كانت عند حفصة وأرسلها إلى الأمصار ليجتمع الناس عليها، أما جمع أبي بكر فكان صحفًا واحدة لم تُوزَّع."] },

  { id: "ulc-005", s: "ulum", g: 1, d: 2, t: ["compilation", "prophetic-era-writing"], src: "al-Bukhārī, Ṣaḥīḥ, Kitāb Faḍāʾil al-Qurʾān, bāb jamʿ al-Qurʾān; al-Suyūṭī, al-Itqān, ch. on collection and arrangement",
    en: ["On what kinds of materials was the Quran written down during the Prophet's lifetime?", ["Palm stalks, thin flat stones and pieces of parchment", "Bound paper volumes produced in the workshops of Medina", "Papyrus scrolls imported from Egypt for the scribes", "Wax tablets kept in the Prophet's mosque for copying"], "Zayd ibn Thābit reports that he gathered the Quran from palm stalks (ʿusub), thin white stones (likhāf) and the memories of men; other reports add parchment and shoulder blades. Bound paper volumes did not exist in Medina at that time."],
    de: ["Auf welche Materialien wurde der Koran zu Lebzeiten des Propheten geschrieben?", ["Palmblattstiele, dünne flache Steine und Pergamentstücke", "Gebundene Papierbände aus den Werkstätten Medinas", "Papyrusrollen, die für die Schreiber aus Ägypten kamen", "Wachstafeln, die in der Moschee des Propheten lagen"], "Zayd ibn Thābit berichtet, er habe den Koran von Palmstielen (ʿusub), dünnen weißen Steinen (likhāf) und aus dem Gedächtnis der Männer gesammelt; andere Berichte nennen Pergament und Schulterblätter. Gebundene Papierbände gab es damals in Medina nicht."],
    ar: ["على أيّ موادّ كُتب القرآن في حياة النبي صلى الله عليه وسلم؟", ["العُسُب واللِّخاف والرِّقاع", "مجلدات ورقية صُنعت في المدينة", "لفائف بردي جُلبت من مصر", "ألواح شمعية حُفظت في المسجد"], "قال زيد بن ثابت إنه تتبّع القرآن يجمعه من العُسُب واللِّخاف وصدور الرجال، وفي روايات أخرى الرِّقاع والأكتاف. ولم تكن المجلدات الورقية معروفة في المدينة آنذاك."] },

  { id: "ulc-006", s: "ulum", g: 2, d: 2, t: ["compilation", "uthman-compilation"], src: "al-Bukhārī, Ṣaḥīḥ, Kitāb Faḍāʾil al-Qurʾān, bāb jamʿ al-Qurʾān",
    en: ["Which Companion came to ʿUthmān alarmed by the differences in recitation among the troops and urged him to act?", ["Ḥudhayfa ibn al-Yamān", "Saʿd ibn Abī Waqqāṣ", "Abū Mūsā al-Ashʿarī", "Salmān al-Fārisī"], "Al-Bukhārī reports that Ḥudhayfa ibn al-Yamān, alarmed by how the people of Syria and Iraq differed in recitation, told ʿUthmān to save the community before it differed over its Book as earlier communities had."],
    de: ["Welcher Gefährte kam beunruhigt über die Unterschiede in der Rezitation unter den Truppen zu ʿUthmān und drängte ihn zu handeln?", ["Ḥudhayfa ibn al-Yamān", "Saʿd ibn Abī Waqqāṣ", "Abū Mūsā al-Ashʿarī", "Salmān al-Fārisī"], "Al-Bukhārī berichtet, dass Ḥudhayfa ibn al-Yamān, beunruhigt über die Unterschiede in der Rezitation zwischen den Leuten Syriens und des Irak, ʿUthmān aufforderte, die Gemeinschaft zu bewahren, bevor sie über ihr Buch uneins würde wie frühere Gemeinschaften."],
    ar: ["مَن الصحابي الذي قدم على عثمان فزِعًا من اختلاف الناس في القراءة وحثّه على تدارك الأمة؟", ["حذيفة بن اليمان", "سعد بن أبي وقاص", "أبو موسى الأشعري", "سلمان الفارسي"], "روى البخاري أن حذيفة بن اليمان أفزعه اختلاف أهل الشام وأهل العراق في القراءة، فقال لعثمان: أدرك هذه الأمة قبل أن يختلفوا في الكتاب كما اختلفت الأمم قبلها."] },

  { id: "ulc-007", s: "ulum", g: 2, d: 3, t: ["compilation", "uthman-compilation"], src: "al-Bukhārī, Ṣaḥīḥ, Kitāb Faḍāʾil al-Qurʾān, bāb jamʿ al-Qurʾān",
    en: ["During which campaign did Ḥudhayfa notice the disputes over recitation that led to ʿUthmān's copies?", ["The conquest of Armenia and Azerbaijan", "The conquest of Egypt and Barqa", "The Battle of al-Qādisiyya in Iraq", "The siege of Jerusalem in Palestine"], "The report in al-Bukhārī places it in the campaign of Armenia and Azerbaijan, where troops from Syria and Iraq fought together and their differing recitations clashed."],
    de: ["Bei welchem Feldzug bemerkte Ḥudhayfa die Streitigkeiten über die Rezitation, die zu ʿUthmāns Abschriften führten?", ["Die Eroberung Armeniens und Aserbaidschans", "Die Eroberung Ägyptens und Barqas", "Die Schlacht von al-Qādisiyya im Irak", "Die Belagerung Jerusalems in Palästina"], "Der Bericht bei al-Bukhārī verortet es im Feldzug gegen Armenien und Aserbaidschan, wo Truppen aus Syrien und dem Irak gemeinsam kämpften und ihre unterschiedlichen Lesarten aufeinandertrafen."],
    ar: ["في أيّ غزوة لاحظ حذيفة اختلاف الناس في القراءة الذي أدّى إلى نسخ المصاحف العثمانية؟", ["فتح أرمينية وأذربيجان", "فتح مصر وبرقة", "معركة القادسية في العراق", "حصار بيت المقدس في الشام"], "في رواية البخاري كان ذلك في غزو أرمينية وأذربيجان، حيث اجتمع جند الشام والعراق فظهر اختلافهم في القراءة."] },

  { id: "ulc-008", s: "ulum", g: 2, d: 2, t: ["compilation", "uthman-compilation"], src: "al-Bukhārī, Ṣaḥīḥ, Kitāb Faḍāʾil al-Qurʾān, bāb jamʿ al-Qurʾān",
    en: ["What did ʿUthmān instruct the committee to do if they differed with Zayd ibn Thābit on how to write something?", ["Write it in the dialect of Quraysh", "Write it in the dialect of Hudhayl", "Write it in the dialect of Tamīm", "Write it in the dialect of the Anṣār"], "ʿUthmān said that the Quran was revealed in the tongue of Quraysh, so in case of difference they should write it in their dialect. Zayd was from the Anṣār, while the other three members were Qurashī."],
    de: ["Was sollte das Komitee nach ʿUthmāns Anweisung tun, wenn es mit Zayd ibn Thābit über die Schreibung uneins war?", ["Es im Dialekt der Quraysh schreiben", "Es im Dialekt der Hudhayl schreiben", "Es im Dialekt der Tamīm schreiben", "Es im Dialekt der Anṣār schreiben"], "ʿUthmān sagte, der Koran sei in der Sprache der Quraysh herabgesandt worden; bei Uneinigkeit solle man in ihrem Dialekt schreiben. Zayd gehörte zu den Anṣār, die drei anderen Mitglieder waren Qurayshiten."],
    ar: ["بماذا أمر عثمانُ اللجنةَ إذا اختلفوا مع زيد بن ثابت في كتابة شيء؟", ["أن يكتبوه بلسان قريش", "أن يكتبوه بلسان هذيل", "أن يكتبوه بلسان تميم", "أن يكتبوه بلسان الأنصار"], "قال عثمان: إذا اختلفتم أنتم وزيد في شيء فاكتبوه بلسان قريش فإنما نزل بلسانهم. وكان زيد أنصاريًّا والثلاثة الآخرون من قريش."] },

  { id: "ulc-009", s: "ulum", g: 3, d: 3, t: ["compilation", "uthman-compilation"], src: "al-Bukhārī, Ṣaḥīḥ, Kitāb Faḍāʾil al-Qurʾān, bāb jamʿ al-Qurʾān",
    en: ["According to al-Bukhārī, which group formed ʿUthmān's committee for copying the muṣḥaf?", ["Zayd ibn Thābit, ʿAbd Allāh ibn al-Zubayr, Saʿīd ibn al-ʿĀṣ, ʿAbd al-Raḥmān ibn al-Ḥārith", "Zayd ibn Thābit, Ubayy ibn Kaʿb, Saʿīd ibn al-ʿĀṣ, ʿAbd Allāh ibn ʿAbbās", "Zayd ibn Thābit, ʿAbd Allāh ibn Masʿūd, ʿAbd Allāh ibn al-Zubayr, Muʿādh ibn Jabal", "Zayd ibn Thābit, Abū al-Dardāʾ, ʿAbd al-Raḥmān ibn ʿAwf, Saʿīd ibn al-ʿĀṣ"], "The report names Zayd ibn Thābit together with three Qurashīs: ʿAbd Allāh ibn al-Zubayr, Saʿīd ibn al-ʿĀṣ and ʿAbd al-Raḥmān ibn al-Ḥārith ibn Hishām. Ubayy and Ibn Masʿūd were great reciters but are not named in this report."],
    de: ["Welche Gruppe bildete laut al-Bukhārī ʿUthmāns Komitee zur Abschrift des Muṣḥaf?", ["Zayd ibn Thābit, ʿAbd Allāh ibn al-Zubayr, Saʿīd ibn al-ʿĀṣ, ʿAbd al-Raḥmān ibn al-Ḥārith", "Zayd ibn Thābit, Ubayy ibn Kaʿb, Saʿīd ibn al-ʿĀṣ, ʿAbd Allāh ibn ʿAbbās", "Zayd ibn Thābit, ʿAbd Allāh ibn Masʿūd, ʿAbd Allāh ibn al-Zubayr, Muʿādh ibn Jabal", "Zayd ibn Thābit, Abū al-Dardāʾ, ʿAbd al-Raḥmān ibn ʿAwf, Saʿīd ibn al-ʿĀṣ"], "Der Bericht nennt Zayd ibn Thābit zusammen mit drei Qurayshiten: ʿAbd Allāh ibn al-Zubayr, Saʿīd ibn al-ʿĀṣ und ʿAbd al-Raḥmān ibn al-Ḥārith ibn Hishām. Ubayy und Ibn Masʿūd waren große Rezitatoren, werden in diesem Bericht aber nicht genannt."],
    ar: ["مَن هم أعضاء لجنة عثمان لنسخ المصاحف كما في رواية البخاري؟", ["زيد بن ثابت وعبد الله بن الزبير وسعيد بن العاص وعبد الرحمن بن الحارث", "زيد بن ثابت وأُبيّ بن كعب وسعيد بن العاص وعبد الله بن عباس", "زيد بن ثابت وعبد الله بن مسعود وعبد الله بن الزبير ومعاذ بن جبل", "زيد بن ثابت وأبو الدرداء وعبد الرحمن بن عوف وسعيد بن العاص"], "سمّت الرواية زيد بن ثابت ومعه ثلاثة من قريش: عبد الله بن الزبير وسعيد بن العاص وعبد الرحمن بن الحارث بن هشام. وكان أُبيّ وابن مسعود من كبار القرّاء ولم يُذكرا في هذه الرواية."] },

  { id: "ulc-010", s: "ulum", g: 2, d: 3, t: ["compilation", "abu-bakr-compilation", "uthman-compilation"], src: "al-Suyūṭī, al-Itqān fī ʿUlūm al-Qurʾān, ch. on collection and arrangement",
    en: ["Which statement best describes the difference in purpose between the compilation of Abū Bakr and that of ʿUthmān?", ["Abū Bakr: gather it lest it be lost; ʿUthmān: unite people on one standard", "Abū Bakr: write it in Quraysh's dialect; ʿUthmān: add the other dialects", "Abū Bakr: gather the Meccan surahs; ʿUthmān: add the Medinan surahs", "Abū Bakr: fix the dotting; ʿUthmān: fix the order of the verses"], "Al-Suyūṭī cites scholars who explain that Abū Bakr's aim was to secure the Quran in one written compilation for fear of loss, while ʿUthmān's aim was to unite the community on standard copies and end disputes over recitation."],
    de: ["Welche Aussage beschreibt den Unterschied im Zweck zwischen der Sammlung Abū Bakrs und der ʿUthmāns am besten?", ["Abū Bakr: Sammeln gegen Verlust; ʿUthmān: Einigung auf einheitliche Abschriften", "Abū Bakr: Schreiben im Quraysh-Dialekt; ʿUthmān: Ergänzen der anderen Dialekte", "Abū Bakr: Sammeln der mekkanischen Suren; ʿUthmān: Ergänzen der medinensischen", "Abū Bakr: Festlegen der Punktierung; ʿUthmān: Festlegen der Versfolge"], "Al-Suyūṭī zitiert Gelehrte, nach denen Abū Bakr den Koran aus Furcht vor Verlust in einer schriftlichen Sammlung sichern wollte, während ʿUthmān die Gemeinschaft auf einheitliche Abschriften einen und den Streit über die Rezitation beenden wollte."],
    ar: ["ما الفرق في الغاية بين جمع أبي بكر وجمع عثمان؟", ["أبو بكر: جمعه خشية ضياعه؛ عثمان: جمع الناس على مصاحف موحدة", "أبو بكر: كتابته بلسان قريش؛ عثمان: إضافة سائر اللهجات", "أبو بكر: جمع السور المكية؛ عثمان: إضافة السور المدنية", "أبو بكر: ضبط النقط؛ عثمان: ترتيب الآيات في السور"], "نقل السيوطي عن العلماء أن جمع أبي بكر كان لخشية ذهاب شيء من القرآن بموت حملته فجُمع في صحف، وأن جمع عثمان كان لجمع الناس على مصاحف موحدة لمّا كثر الاختلاف في القراءة."] },

  { id: "ulc-011", s: "ulum", g: 3, d: 3, t: ["compilation", "abu-bakr-compilation", "tawatur"], v: "9:128", src: "al-Bukhārī, Ṣaḥīḥ, Kitāb Faḍāʾil al-Qurʾān, bāb jamʿ al-Qurʾān; Ibn Ḥajar, Fatḥ al-Bārī, on the same chapter",
    en: ["Zayd reported that he found the end of Sūrat al-Tawba (the verse shown and the next) only with Abū Khuzayma al-Anṣārī. How do scholars understand this?", ["He found it in written form with no one else, though many had memorised it", "Only one Companion had memorised it, so it rests on a single report", "No other Companion had heard these verses before", "All other written copies had lost it through abrogation"], "Ibn Ḥajar and others explain that Zayd sought every verse in writing as well as from memory; these verses were known and memorised by many, but the written piece was found only with Abū Khuzayma. The Quran's transmission therefore did not rest on one person."],
    de: ["Zayd berichtete, er habe das Ende der Sūrat al-Tawba (den gezeigten Vers und den nächsten) nur bei Abū Khuzayma al-Anṣārī gefunden. Wie verstehen die Gelehrten das?", ["Schriftlich fand er es nur bei ihm, doch viele hatten es auswendig gelernt", "Nur ein Gefährte hatte es auswendig gelernt, es beruht also auf einem Einzelbericht", "Kein anderer Gefährte hatte diese Verse vorher gehört", "Alle anderen Schriftstücke hatten es durch Abrogation verloren"], "Ibn Ḥajar und andere erklären, dass Zayd jeden Vers schriftlich und aus dem Gedächtnis suchte; diese Verse waren vielen bekannt und auswendig vertraut, doch das Schriftstück fand sich nur bei Abū Khuzayma. Die Überlieferung des Korans hing also nicht an einer Person."],
    ar: ["ذكر زيد أنه وجد آخر سورة التوبة (الآية المعروضة والتي بعدها) مع أبي خزيمة الأنصاري لم يجدها مع غيره. كيف فهم العلماء ذلك؟", ["لم يجدها مكتوبة عند غيره وكان كثيرون يحفظونها", "لم يحفظها إلا صحابي واحد فثبتت بخبر آحاد", "لم يسمعها أحد من الصحابة قبل ذلك اليوم", "سقطت من سائر الصحف المكتوبة بسبب النسخ"], "بيّن ابن حجر وغيره أن زيدًا كان يطلب كل آية مكتوبة مع الحفظ، وكانت هذه الآيات محفوظة عند كثيرين، وإنما لم يجدها مكتوبة إلا عند أبي خزيمة، فلم يتوقف ثبوت القرآن على واحد."] },

  { id: "ulc-012", s: "ulum", g: 3, d: 4, t: ["compilation", "uthman-compilation"], v: "33:23", src: "al-Bukhārī, Ṣaḥīḥ, Kitāb Faḍāʾil al-Qurʾān, bāb jamʿ al-Qurʾān",
    en: ["According to al-Bukhārī, with whom did Zayd find the verse shown (from al-Aḥzāb) in writing while copying the muṣḥaf under ʿUthmān?", ["Khuzayma ibn Thābit al-Anṣārī", "Abū Khuzayma al-Anṣārī", "Ubayy ibn Kaʿb al-Anṣārī", "Anas ibn Mālik al-Anṣārī"], "Zayd said he missed a verse of al-Aḥzāb that he had heard the Prophet recite and found it with Khuzayma ibn Thābit, whose testimony the Prophet had counted as that of two men. The end of al-Tawba, by contrast, was found with Abū Khuzayma during Abū Bakr's compilation."],
    de: ["Bei wem fand Zayd laut al-Bukhārī den gezeigten Vers (aus al-Aḥzāb) schriftlich, als unter ʿUthmān der Muṣḥaf abgeschrieben wurde?", ["Khuzayma ibn Thābit al-Anṣārī", "Abū Khuzayma al-Anṣārī", "Ubayy ibn Kaʿb al-Anṣārī", "Anas ibn Mālik al-Anṣārī"], "Zayd sagte, ihm habe ein Vers aus al-Aḥzāb gefehlt, den er den Propheten hatte rezitieren hören; er fand ihn bei Khuzayma ibn Thābit, dessen Zeugnis der Prophet wie das zweier Männer gewertet hatte. Das Ende von al-Tawba wurde dagegen bei der Sammlung Abū Bakrs bei Abū Khuzayma gefunden."],
    ar: ["عند مَن وجد زيدٌ الآيةَ المعروضة من سورة الأحزاب مكتوبةً عند نسخ المصاحف في عهد عثمان كما في البخاري؟", ["خزيمة بن ثابت الأنصاري", "أبو خزيمة الأنصاري", "أُبيّ بن كعب الأنصاري", "أنس بن مالك الأنصاري"], "قال زيد: فقدت آية من الأحزاب كنت أسمع رسول الله صلى الله عليه وسلم يقرأ بها، فوجدتها مع خزيمة بن ثابت الذي جعل النبي شهادته بشهادة رجلين. أما آخر التوبة فوُجد مع أبي خزيمة في جمع أبي بكر."] },

  { id: "ulc-013", s: "ulum", g: 2, d: 3, t: ["compilation", "uthman-compilation"], src: "al-Suyūṭī, al-Itqān fī ʿUlūm al-Qurʾān, ch. on collection and arrangement",
    en: ["Which of these cities is commonly listed among the destinations of the copies sent by ʿUthmān?", ["Kufa", "Baghdad", "Cairo", "Qayrawān"], "The reports commonly name Kufa, Basra, Syria and Mecca besides the copy kept in Medina, though the exact number of copies is disputed. Baghdad, Cairo and Qayrawān were all founded after ʿUthmān's death."],
    de: ["Welche dieser Städte wird häufig unter den Zielorten der von ʿUthmān versandten Abschriften genannt?", ["Kufa", "Bagdad", "Kairo", "Qayrawān"], "Die Berichte nennen gewöhnlich Kufa, Basra, Syrien und Mekka neben dem in Medina verbliebenen Exemplar, wobei die genaue Zahl der Abschriften umstritten ist. Bagdad, Kairo und Qayrawān wurden alle erst nach ʿUthmāns Tod gegründet."],
    ar: ["أيّ هذه المدن يُذكر عادةً بين الأمصار التي أُرسلت إليها المصاحف العثمانية؟", ["الكوفة", "بغداد", "القاهرة", "القيروان"], "تذكر الروايات غالبًا الكوفة والبصرة والشام ومكة مع المصحف الذي بقي في المدينة، مع اختلاف في عدد المصاحف. أما بغداد والقاهرة والقيروان فقد أُسّست بعد وفاة عثمان."] },

  { id: "ulc-014", s: "ulum", g: 2, d: 3, t: ["compilation", "prophetic-era-writing"], src: "al-Zarkashī, al-Burhān fī ʿUlūm al-Qurʾān, ch. on collection; al-Suyūṭī, al-Itqān, ch. on collection and arrangement",
    en: ["Why, according to scholars such as al-Khaṭṭābī, was the Quran not bound into a single volume during the Prophet's lifetime?", ["Revelation was still ongoing and abrogation was still possible", "Writing materials were forbidden for recording the revelation", "The Companions disliked writing down anything besides hadith", "The Prophet ordered that it be preserved only in memory"], "Al-Suyūṭī quotes al-Khaṭṭābī: the Prophet did not gather it in one muṣḥaf because he expected further revelation or abrogation. Once revelation ended with his death, the Companions gathered it."],
    de: ["Warum wurde der Koran nach Gelehrten wie al-Khaṭṭābī zu Lebzeiten des Propheten nicht in einem Band gebunden?", ["Die Offenbarung dauerte an, und Abrogation war noch möglich", "Schreibmaterial war für die Offenbarung nicht erlaubt", "Die Gefährten schrieben ungern etwas außer Hadith auf", "Der Prophet befahl, ihn nur im Gedächtnis zu bewahren"], "Al-Suyūṭī zitiert al-Khaṭṭābī: Der Prophet sammelte ihn nicht in einem Muṣḥaf, weil er weitere Offenbarung oder Abrogation erwartete. Als die Offenbarung mit seinem Tod endete, sammelten ihn die Gefährten."],
    ar: ["لماذا لم يُجمع القرآن في مصحف واحد في حياة النبي صلى الله عليه وسلم كما ذكر الخطابي وغيره؟", ["لأن الوحي كان مستمرًّا والنسخ واردًا", "لأن الكتابة كانت ممنوعة في تدوين الوحي", "لأن الصحابة كرهوا كتابة غير الحديث", "لأن النبي أمر بحفظه في الصدور فقط"], "نقل السيوطي عن الخطابي أن النبي صلى الله عليه وسلم لم يجمع القرآن في مصحف لما كان يترقّبه من ورود ناسخ لبعض أحكامه أو تلاوته، فلما انقضى نزوله بوفاته جمعه الصحابة."] },

  { id: "ulc-015", s: "ulum", g: 4, d: 5, t: ["compilation", "uthman-compilation", "seven-ahruf"], src: "al-Ṭabarī, Jāmiʿ al-Bayān, introduction; Ibn al-Jazarī, al-Nashr fī al-Qirāʾāt al-ʿAshr, introduction",
    en: ["Which scholar is known for the view that the ʿUthmānic copies preserve only one of the seven aḥruf?", ["Ibn Jarīr al-Ṭabarī", "Ibn al-Jazarī", "Ibn Qutayba", "Abū al-Faḍl al-Rāzī"], "Al-Ṭabarī held that ʿUthmān united the community on a single ḥarf and the others were left. Ibn al-Jazarī reports the majority view that the copies contain whatever of the aḥruf their script can bear; Ibn Qutayba and Abū al-Faḍl al-Rāzī explained the aḥruf as types of variation found within the readings."],
    de: ["Welcher Gelehrte ist für die Ansicht bekannt, dass die ʿuthmānischen Abschriften nur einen der sieben aḥruf bewahren?", ["Ibn Jarīr al-Ṭabarī", "Ibn al-Jazarī", "Ibn Qutayba", "Abū al-Faḍl al-Rāzī"], "Al-Ṭabarī vertrat, dass ʿUthmān die Gemeinschaft auf einen einzigen ḥarf einte und die übrigen aufgegeben wurden. Ibn al-Jazarī gibt die Mehrheitsansicht wieder, dass die Abschriften enthalten, was ihr Schriftbild von den aḥruf tragen kann; Ibn Qutayba und Abū al-Faḍl al-Rāzī deuteten die aḥruf als Arten von Varianz innerhalb der Lesarten."],
    ar: ["مَن العالم المعروف بالقول إن المصاحف العثمانية لم تحفظ إلا حرفًا واحدًا من الأحرف السبعة؟", ["ابن جرير الطبري", "ابن الجزري", "ابن قتيبة", "أبو الفضل الرازي"], "ذهب الطبري إلى أن عثمان جمع الأمة على حرف واحد وتُركت سائر الأحرف. ونقل ابن الجزري قول الجمهور إن المصاحف مشتملة على ما يحتمله رسمها من الأحرف، وفسّر ابن قتيبة وأبو الفضل الرازي الأحرف بأوجه الاختلاف الموجودة في القراءات."] },

  // ---- rasm, dotting and vowelling ----
  { id: "ulc-016", s: "ulum", g: 1, d: 1, t: ["rasm", "uthmani-script"], src: "al-Suyūṭī, al-Itqān fī ʿUlūm al-Qurʾān, ch. on the script of the muṣḥaf",
    en: ["What does the term al-rasm al-ʿuthmānī refer to?", ["The spelling conventions of the copies made under ʿUthmān", "The rules of pausing that ʿUthmān followed in the prayer", "The order of the surahs as fixed by ʿUthmān's committee", "A style of calligraphy that was invented in ʿUthmān's era"], "Al-rasm al-ʿuthmānī is the way words are spelled in the copies written by ʿUthmān's committee, which sometimes differs from ordinary Arabic spelling. It concerns spelling, not a particular calligraphic hand."],
    de: ["Worauf bezieht sich der Begriff al-rasm al-ʿuthmānī?", ["Die Schreibkonventionen der unter ʿUthmān angefertigten Abschriften", "Die Pausenregeln, die ʿUthmān beim Rezitieren im Gebet befolgte", "Die Reihenfolge der Suren, wie ʿUthmāns Komitee sie festlegte", "Ein Kalligrafiestil, der in der Zeit ʿUthmāns erfunden wurde"], "Al-rasm al-ʿuthmānī ist die Art, wie Wörter in den Abschriften von ʿUthmāns Komitee geschrieben sind; sie weicht teils von der üblichen arabischen Orthografie ab. Es geht um die Schreibung, nicht um eine bestimmte Schriftart."],
    ar: ["ما المقصود بالرسم العثماني؟", ["طريقة كتابة الكلمات في المصاحف التي نُسخت في عهد عثمان", "قواعد الوقف التي كان عثمان يلتزمها في الصلاة", "ترتيب السور الذي وضعته لجنة عثمان في المصاحف", "نوع من الخط العربي الجميل ابتُكر في عهد عثمان"], "الرسم العثماني هو الهيئة التي كُتبت عليها كلمات القرآن في المصاحف التي نسختها لجنة عثمان، وقد يخالف القياس الإملائي أحيانًا. وهو متعلق بهجاء الكلمات لا بنوع الخط."] },

  { id: "ulc-017", s: "ulum", g: 1, d: 2, t: ["dotting-vowelling", "abu-al-aswad"], src: "Abū ʿAmr al-Dānī, al-Muḥkam fī Naqṭ al-Maṣāḥif, introduction",
    en: ["Who is commonly credited with first marking the vowels of the muṣḥaf with dots?", ["Abū al-Aswad al-Duʾalī", "al-Khalīl ibn Aḥmad al-Farāhīdī", "Sībawayh", "al-Ḥajjāj ibn Yūsuf"], "Most accounts credit Abū al-Aswad al-Duʾalī with the first vowel marks, coloured dots placed around the letters. Al-Khalīl later replaced these dots with the signs used today."],
    de: ["Wem wird gewöhnlich zugeschrieben, als Erster die Vokale im Muṣḥaf mit Punkten markiert zu haben?", ["Abū al-Aswad al-Duʾalī", "al-Khalīl ibn Aḥmad al-Farāhīdī", "Sībawayh", "al-Ḥajjāj ibn Yūsuf"], "Die meisten Berichte schreiben Abū al-Aswad al-Duʾalī die ersten Vokalzeichen zu: farbige Punkte um die Buchstaben. Al-Khalīl ersetzte diese Punkte später durch die heute üblichen Zeichen."],
    ar: ["مَن يُنسب إليه عادةً أنه أول من ضبط حركات المصحف بالنقط؟", ["أبو الأسود الدؤلي", "الخليل بن أحمد الفراهيدي", "سيبويه", "الحجاج بن يوسف"], "تنسب أكثر الروايات إلى أبي الأسود الدؤلي أول نقط للحركات، وهو نقط بلون مخالف حول الحروف، ثم أبدله الخليل بالحركات المعروفة اليوم."] },

  { id: "ulc-018", s: "ulum", g: 2, d: 2, t: ["dotting-vowelling", "al-khalil"], src: "Abū ʿAmr al-Dānī, al-Muḥkam fī Naqṭ al-Maṣāḥif",
    en: ["Who replaced the vowel dots with the vowel signs used in the muṣḥaf today?", ["al-Khalīl ibn Aḥmad al-Farāhīdī", "Abū al-Aswad al-Duʾalī", "Naṣr ibn ʿĀṣim al-Laythī", "ʿAlī ibn Ḥamza al-Kisāʾī"], "Al-Khalīl ibn Aḥmad derived the signs from letters: a small alif for fatḥa, a small wāw for ḍamma and a small yāʾ for kasra, together with signs for shadda and sukūn. Abū al-Aswad had used dots, and Naṣr worked on the dots that distinguish letters."],
    de: ["Wer ersetzte die Vokalpunkte durch die Vokalzeichen, die heute im Muṣḥaf stehen?", ["al-Khalīl ibn Aḥmad al-Farāhīdī", "Abū al-Aswad al-Duʾalī", "Naṣr ibn ʿĀṣim al-Laythī", "ʿAlī ibn Ḥamza al-Kisāʾī"], "Al-Khalīl ibn Aḥmad leitete die Zeichen aus Buchstaben ab: ein kleines Alif für fatḥa, ein kleines Wāw für ḍamma, ein kleines Yāʾ für kasra, dazu Zeichen für shadda und sukūn. Abū al-Aswad hatte Punkte verwendet, Naṣr arbeitete an den Punkten zur Unterscheidung der Buchstaben."],
    ar: ["مَن أبدل نقط الإعراب بالحركات المستعملة في المصحف اليوم؟", ["الخليل بن أحمد الفراهيدي", "أبو الأسود الدؤلي", "نصر بن عاصم الليثي", "علي بن حمزة الكسائي"], "أخذ الخليل بن أحمد الحركات من صور الحروف: ألفًا صغيرة للفتحة وواوًا صغيرة للضمة وياءً صغيرة للكسرة، ووضع علامتي الشدة والسكون. أما أبو الأسود فكان نقطه بالنقاط، ونصر عمل في نقط الإعجام."] },

  { id: "ulc-019", s: "ulum", g: 2, d: 3, t: ["dotting-vowelling", "naqt-al-ijam"], src: "Abū ʿAmr al-Dānī, al-Muḥkam fī Naqṭ al-Maṣāḥif; al-Suyūṭī, al-Itqān, ch. on the script of the muṣḥaf",
    en: ["What contribution is attributed to Naṣr ibn ʿĀṣim and Yaḥyā ibn Yaʿmar?", ["The dots that tell apart letters of the same shape", "The first coloured dots that marked the vowels", "The division of the muṣḥaf into thirty parts", "The signs for shadda and sukūn above letters"], "They are credited with naqṭ al-iʿjām, the dots that distinguish letters of the same shape. Vowel dots (naqṭ al-iʿrāb) are attributed to Abū al-Aswad, and the shadda and sukūn signs to al-Khalīl."],
    de: ["Welcher Beitrag wird Naṣr ibn ʿĀṣim und Yaḥyā ibn Yaʿmar zugeschrieben?", ["Die Punkte, die gleich geformte Buchstaben unterscheiden", "Die ersten farbigen Punkte zur Kennzeichnung der Vokale", "Die Einteilung des Muṣḥaf in dreißig Teile", "Die Zeichen für shadda und sukūn über den Buchstaben"], "Ihnen wird naqṭ al-iʿjām zugeschrieben, die Punkte, die Buchstaben gleicher Grundform unterscheiden. Die Vokalpunkte (naqṭ al-iʿrāb) gehen auf Abū al-Aswad zurück, shadda- und sukūn-Zeichen auf al-Khalīl."],
    ar: ["ما العمل الذي يُنسب إلى نصر بن عاصم ويحيى بن يعمر؟", ["نقط الإعجام المميِّز للحروف المتشابهة", "أول نقط ملوّن لبيان حركات الإعراب", "تقسيم المصحف إلى ثلاثين جزءًا", "وضع علامتي الشدة والسكون فوق الحروف"], "يُنسب إليهما نقط الإعجام الذي يفرّق بين الحروف المتشابهة في الصورة. أما نقط الإعراب فيُنسب إلى أبي الأسود، وعلامتا الشدة والسكون إلى الخليل."] },

  { id: "ulc-020", s: "ulum", g: 2, d: 3, t: ["dotting-vowelling", "abu-al-aswad"], src: "Abū ʿAmr al-Dānī, al-Muḥkam fī Naqṭ al-Maṣāḥif",
    en: ["In the vowel-dot system of Abū al-Aswad al-Duʾalī, what did a dot placed above the letter indicate?", ["Fatḥa", "Kasra", "Ḍamma", "Sukūn"], "Abū al-Aswad told his scribe to put a dot above the letter when he opened his mouth (fatḥa), below it when he lowered it (kasra), and in front of it when he rounded his lips (ḍamma); two dots marked tanwīn."],
    de: ["Was bedeutete im Vokalpunktsystem des Abū al-Aswad al-Duʾalī ein Punkt über dem Buchstaben?", ["Fatḥa", "Kasra", "Ḍamma", "Sukūn"], "Abū al-Aswad wies seinen Schreiber an, einen Punkt über den Buchstaben zu setzen, wenn er den Mund öffnete (fatḥa), darunter, wenn er ihn senkte (kasra), und davor, wenn er die Lippen rundete (ḍamma); zwei Punkte bezeichneten das tanwīn."],
    ar: ["في نقط أبي الأسود الدؤلي، علامَ تدل النقطة فوق الحرف؟", ["الفتحة", "الكسرة", "الضمة", "السكون"], "قال أبو الأسود لكاتبه: إذا فتحتُ شفتيّ فانقط واحدة فوق الحرف، وإذا كسرتهما فاجعل النقطة تحته، وإذا ضممتهما فاجعلها بين يدي الحرف، فإن أتبعتُ ذلك غنّة فانقط نقطتين."] },

  { id: "ulc-021", s: "ulum", g: 3, d: 4, t: ["dotting-vowelling", "al-khalil"], src: "Abū ʿAmr al-Dānī, al-Muḥkam fī Naqṭ al-Maṣāḥif",
    en: ["In al-Khalīl's system of signs, from what is the shadda sign derived?", ["The head of the letter shīn", "The head of the letter khāʾ", "The head of the letter ʿayn", "A small letter dāl"], "Al-Khalīl took the shadda from the head of shīn (for shadīd), the sukūn in one form from the head of khāʾ (for khafīf), and the hamza from the head of ʿayn, because of the closeness of their points of articulation."],
    de: ["Woraus ist im Zeichensystem al-Khalīls das shadda-Zeichen abgeleitet?", ["Aus dem Kopf des Buchstabens shīn", "Aus dem Kopf des Buchstabens khāʾ", "Aus dem Kopf des Buchstabens ʿayn", "Aus einem kleinen Buchstaben dāl"], "Al-Khalīl nahm die shadda vom Kopf des shīn (für shadīd), das sukūn in einer Form vom Kopf des khāʾ (für khafīf) und die hamza vom Kopf des ʿayn, wegen der Nähe ihrer Artikulationsstellen."],
    ar: ["في علامات الخليل، من أيّ شيء أُخذت علامة الشدة؟", ["من رأس الشين", "من رأس الخاء", "من رأس العين", "من دال صغيرة"], "أخذ الخليل الشدة من رأس الشين أول كلمة شديد، والسكون في إحدى صوره من رأس الخاء أول كلمة خفيف، والهمزة من رأس العين لقرب المخرج."] },

  { id: "ulc-022", s: "ulum", g: 3, d: 4, t: ["rasm", "uthmani-script"], src: "al-Suyūṭī, al-Itqān fī ʿUlūm al-Qurʾān, ch. on the script of the muṣḥaf",
    en: ["Al-Suyūṭī groups the rules of the ʿUthmānic script under six headings. Which set matches them?", ["Omission, addition, hamza, substitution, joining and separating, variant words", "Clear pronunciation, assimilation, conversion, concealment, lengthening, echo", "Dotting, vowelling, pausing, starting, verse counting and dividing into parts", "The vowel signs fatḥa, kasra and ḍamma, with sukūn, shadda and tanwīn"], "In al-Itqān the rasm is treated under ḥadhf, ziyāda, hamz, badal, waṣl and faṣl, and words read in two ways but written according to one of them. The other sets are tajwīd rules, other muṣḥaf sciences or vowel signs."],
    de: ["Al-Suyūṭī ordnet die Regeln der ʿuthmānischen Schreibung sechs Überschriften zu. Welche Reihe entspricht ihnen?", ["Auslassung, Hinzufügung, hamza, Ersetzung, Verbinden/Trennen, Wörter mit zwei Lesarten", "Deutliche Aussprache, Assimilation, Umwandlung, Verbergen, Dehnung, Nachhall", "Punktierung, Vokalisierung, Pausieren, Beginnen, Verszählung und Einteilung", "Die Vokalzeichen fatḥa, kasra und ḍamma sowie sukūn, shadda und tanwīn"], "In al-Itqān wird der rasm unter ḥadhf, ziyāda, hamz, badal, waṣl und faṣl sowie Wörtern behandelt, die zweifach gelesen, aber nach einer Lesart geschrieben werden. Die anderen Reihen sind Tajwīd-Regeln, andere Muṣḥaf-Wissenschaften oder Vokalzeichen."],
    ar: ["جعل السيوطي قواعد الرسم العثماني في ست قواعد. ما المجموعة الموافقة لها؟", ["الحذف والزيادة والهمز والبدل والوصل والفصل وما فيه قراءتان", "الإظهار والإدغام والإقلاب والإخفاء والمد والقلقلة وأقسامها", "النقط والشكل والوقف والابتداء وعدّ الآي والتجزئة", "الفتحة والكسرة والضمة والسكون والشدة والتنوين وصورها"], "ذكر السيوطي في الإتقان أن الرسم ينحصر في ست قواعد: الحذف والزيادة والهمز والبدل والوصل والفصل وما فيه قراءتان فكُتب على إحداهما. أما بقية المجموعات فأحكام تجويد أو علوم أخرى للمصحف أو علامات حركات."] },

  { id: "ulc-023", s: "ulum", g: 2, d: 3, t: ["rasm", "uthmani-script", "qiraat-and-rasm"], v: "1:4", w: 1, src: "Abū ʿAmr al-Dānī, al-Muqniʿ fī Rasm Maṣāḥif al-Amṣār; Ibn al-Jazarī, al-Nashr, introduction",
    en: ["In the ʿUthmānic rasm the highlighted word has no full alif after the mīm (the small alif is a later reading sign). What is the significance of this?", ["The spelling carries both readings, māliki and maliki", "It marks a compulsory pause at this word in recitation", "It shows that the word may only be read with a short vowel", "It reflects a dialect form used by the tribe of Hudhayl"], "Writing the word without the alif allows both established readings, māliki (with a long ā) and maliki. This is one of the ways the rasm was able to carry more than one reading."],
    de: ["Im ʿuthmānischen rasm hat das hervorgehobene Wort kein volles Alif nach dem mīm (das kleine Alif ist ein späteres Lesezeichen). Welche Bedeutung hat das?", ["Die Schreibung trägt beide Lesarten, māliki und maliki", "Sie zeigt eine verpflichtende Pause bei diesem Wort an", "Sie zeigt, dass das Wort nur mit kurzem Vokal gelesen wird", "Sie gibt eine Dialektform des Stammes Hudhayl wieder"], "Die Schreibung ohne Alif lässt beide überlieferten Lesarten zu, māliki (mit langem ā) und maliki. So konnte der rasm mehr als eine Lesart tragen."],
    ar: ["رُسمت الكلمة المظللة في الرسم العثماني بلا ألف بعد الميم (والألف الصغيرة علامة ضبط متأخرة). ما فائدة ذلك؟", ["أن الرسم يحتمل القراءتين: مالك ومَلِك", "أنه علامة على وقف لازم عند هذه الكلمة", "أن الكلمة لا تُقرأ إلا بالقصر وحده", "أنه يحكي لهجة من لهجات قبيلة هذيل"], "حذف الألف في الرسم يجعل الكلمة محتملة للقراءتين الثابتتين: بالمد (مالك) وبالقصر (مَلِك)، وهذا من وجوه احتمال الرسم لأكثر من قراءة."] },

  { id: "ulc-024", s: "ulum", g: 4, d: 4, t: ["rasm", "ruling-on-rasm"], tr: ["maliki"], src: "Abū ʿAmr al-Dānī, al-Muqniʿ fī Rasm Maṣāḥif al-Amṣār; al-Suyūṭī, al-Itqān, ch. on the script of the muṣḥaf",
    en: ["Asked whether a muṣḥaf may be written in the spelling that people had newly devised, which imam answered that it should be written according to the first writing?", ["Mālik ibn Anas", "al-Shāfiʿī", "Abū Ḥanīfa", "al-Layth ibn Saʿd"], "Al-Dānī reports through Ashhab that Mālik was asked this and replied that it should be written only according to the first writing. Al-Dānī adds that no scholar opposed him; many later scholars held following the rasm to be obligatory."],
    de: ["Welcher Imam antwortete auf die Frage, ob ein Muṣḥaf in der neu entstandenen Schreibweise geschrieben werden dürfe, man solle ihn nach der ersten Schreibung schreiben?", ["Mālik ibn Anas", "al-Shāfiʿī", "Abū Ḥanīfa", "al-Layth ibn Saʿd"], "Al-Dānī berichtet über Ashhab, dass Mālik dies gefragt wurde und antwortete, man solle ihn nur nach der ersten Schreibung schreiben. Al-Dānī fügt hinzu, dass ihm kein Gelehrter widersprach; viele spätere Gelehrte hielten die Befolgung des rasm für verpflichtend."],
    ar: ["سُئل أحد الأئمة: هل يُكتب المصحف على ما أحدثه الناس من الهجاء؟ فقال: لا، إلا على الكتبة الأولى. مَن هو؟", ["مالك بن أنس", "الشافعي", "أبو حنيفة", "الليث بن سعد"], "روى الداني من طريق أشهب أن مالكًا سُئل عن ذلك فقال: لا، إلا على الكتبة الأولى. قال الداني: ولا مخالف له من علماء الأمة، وذهب كثير من العلماء بعده إلى وجوب التزام الرسم."] },

  { id: "ulc-025", s: "ulum", g: 4, d: 5, t: ["rasm", "ruling-on-rasm"], src: "al-Zarkashī, al-Burhān fī ʿUlūm al-Qurʾān, ch. on the script of the muṣḥaf",
    en: ["Which scholar, as reported by al-Zarkashī, held that copies for the general public should be written in the familiar spelling so that the uneducated would not misread them?", ["al-ʿIzz ibn ʿAbd al-Salām", "Mālik ibn Anas al-Aṣbaḥī", "Aḥmad ibn Muḥammad ibn Ḥanbal", "Abū ʿAmr ʿUthmān al-Dānī"], "Al-Zarkashī quotes al-ʿIzz ibn ʿAbd al-Salām saying that the muṣḥaf should not now be written in the first spelling for fear that the ignorant would alter it; al-Zarkashī adds that the old rasm must still be preserved by scholars. Mālik, Aḥmad and al-Dānī are associated with holding to the first writing."],
    de: ["Welcher Gelehrte vertrat laut al-Zarkashī, dass Abschriften für die Allgemeinheit in der gewohnten Schreibweise zu schreiben seien, damit Ungebildete nicht falsch lesen?", ["al-ʿIzz ibn ʿAbd al-Salām", "Mālik ibn Anas al-Aṣbaḥī", "Aḥmad ibn Muḥammad ibn Ḥanbal", "Abū ʿAmr ʿUthmān al-Dānī"], "Al-Zarkashī zitiert al-ʿIzz ibn ʿAbd al-Salām, man solle den Muṣḥaf heute nicht in der ersten Schreibung schreiben, damit Unwissende ihn nicht verändern; al-Zarkashī ergänzt, dass die alte Schreibung dennoch von Gelehrten bewahrt werden müsse. Mālik, Aḥmad und al-Dānī stehen für das Festhalten an der ersten Schreibung."],
    ar: ["مَن العالم الذي نقل عنه الزركشي أنه لا يجوز كتابة المصحف الآن على الرسوم الأولى لئلا يوقع في تغيير من الجهّال؟", ["العز بن عبد السلام", "مالك بن أنس الأصبحي", "أحمد بن محمد بن حنبل", "أبو عمرو عثمان الداني"], "نقل الزركشي عن العز بن عبد السلام هذا القول، ثم قال إنه لا ينبغي إجراء هذا على إطلاقه لئلا يؤدي إلى دروس العلم، فيُحفظ الرسم الأول عند العلماء. أما مالك وأحمد والداني فمعروفون بالتزام الكتبة الأولى."] },

  { id: "ulc-026", s: "ulum", g: 3, d: 4, t: ["rasm", "works-on-rasm"], src: "Abū ʿAmr al-Dānī, al-Muqniʿ fī Rasm Maṣāḥif al-Amṣār",
    en: ["Which work by Abū ʿAmr al-Dānī is a foundational reference on the spelling of the ʿUthmānic copies?", ["al-Muqniʿ fī Rasm Maṣāḥif al-Amṣār", "al-Taysīr fī al-Qirāʾāt al-Sabʿ", "al-Nashr fī al-Qirāʾāt al-ʿAshr", "Ḥirz al-Amānī wa-Wajh al-Tahānī"], "Al-Muqniʿ collects the spellings of the copies of the various cities. Al-Taysīr is al-Dānī's work on the seven readings, al-Nashr is by Ibn al-Jazarī and Ḥirz al-Amānī is al-Shāṭibī's poem on the readings."],
    de: ["Welches Werk von Abū ʿAmr al-Dānī ist ein grundlegendes Nachschlagewerk zur Schreibung der ʿuthmānischen Abschriften?", ["al-Muqniʿ fī Rasm Maṣāḥif al-Amṣār", "al-Taysīr fī al-Qirāʾāt al-Sabʿ", "al-Nashr fī al-Qirāʾāt al-ʿAshr", "Ḥirz al-Amānī wa-Wajh al-Tahānī"], "Al-Muqniʿ sammelt die Schreibungen der Abschriften der verschiedenen Städte. Al-Taysīr ist al-Dānīs Werk über die sieben Lesarten, al-Nashr stammt von Ibn al-Jazarī, und Ḥirz al-Amānī ist al-Shāṭibīs Lehrgedicht über die Lesarten."],
    ar: ["ما كتاب أبي عمرو الداني الذي يُعدّ أصلًا في رسم المصاحف العثمانية؟", ["المقنع في رسم مصاحف الأمصار", "التيسير في القراءات السبع", "النشر في القراءات العشر", "حرز الأماني ووجه التهاني"], "جمع الداني في المقنع رسم مصاحف الأمصار. أما التيسير فكتابه في القراءات السبع، والنشر لابن الجزري، وحرز الأماني منظومة الشاطبي في القراءات."] },

  { id: "ulc-027", s: "ulum", g: 4, d: 5, t: ["rasm", "works-on-rasm"], src: "al-Shāṭibī, ʿAqīlat Atrāb al-Qaṣāʾid; Abū ʿAmr al-Dānī, al-Muqniʿ",
    en: ["Which poem by al-Shāṭibī versifies the content of al-Dānī's al-Muqniʿ on the rasm?", ["ʿAqīlat Atrāb al-Qaṣāʾid", "Ḥirz al-Amānī wa-Wajh al-Tahānī", "Nāẓimat al-Zuhr", "al-Durra al-Muḍīʾa"], "Al-Shāṭibī put al-Muqniʿ into verse in ʿAqīlat Atrāb al-Qaṣāʾid (often called al-Rāʾiyya). Ḥirz al-Amānī versifies al-Taysīr on the readings, Nāẓimat al-Zuhr deals with verse counting, and al-Durra al-Muḍīʾa is Ibn al-Jazarī's poem on the three additional readings."],
    de: ["Welches Lehrgedicht al-Shāṭibīs bringt den Inhalt von al-Dānīs al-Muqniʿ über den rasm in Verse?", ["ʿAqīlat Atrāb al-Qaṣāʾid", "Ḥirz al-Amānī wa-Wajh al-Tahānī", "Nāẓimat al-Zuhr", "al-Durra al-Muḍīʾa"], "Al-Shāṭibī versifizierte al-Muqniʿ in ʿAqīlat Atrāb al-Qaṣāʾid (oft al-Rāʾiyya genannt). Ḥirz al-Amānī versifiziert al-Taysīr über die Lesarten, Nāẓimat al-Zuhr behandelt die Verszählung, und al-Durra al-Muḍīʾa ist Ibn al-Jazarīs Gedicht über die drei zusätzlichen Lesarten."],
    ar: ["ما منظومة الشاطبي التي نظم فيها كتاب المقنع للداني في الرسم؟", ["عقيلة أتراب القصائد", "حرز الأماني ووجه التهاني", "ناظمة الزهر", "الدرة المضية"], "نظم الشاطبي المقنع في عقيلة أتراب القصائد المعروفة بالرائية. أما حرز الأماني فنظم التيسير في القراءات، وناظمة الزهر في عدّ الآي، والدرة المضية لابن الجزري في القراءات الثلاث المتممة للعشر."] },

  // ---- order of surahs and verses, divisions ----
  { id: "ulc-028", s: "ulum", g: 1, d: 1, t: ["surah-order", "quran-structure"], src: "al-Suyūṭī, al-Itqān fī ʿUlūm al-Qurʾān, ch. on the number of surahs",
    en: ["How many surahs does the Quran contain?", ["114", "110", "120", "99"], "The muṣḥaf contains 114 surahs, beginning with al-Fātiḥa and ending with al-Nās."],
    de: ["Wie viele Suren enthält der Koran?", ["114", "110", "120", "99"], "Der Muṣḥaf enthält 114 Suren, beginnend mit al-Fātiḥa und endend mit al-Nās."],
    ar: ["كم عدد سور القرآن الكريم؟", ["مئة وأربع عشرة", "مئة وعشر", "مئة وعشرون", "تسع وتسعون"], "عدد سور المصحف مئة وأربع عشرة سورة، أولها الفاتحة وآخرها الناس."] },

  { id: "ulc-029", s: "ulum", g: 2, d: 2, t: ["verse-order", "tawqifi"], tr: ["ijma"], src: "al-Zarkashī, al-Burhān, ch. on the order of verses; al-Suyūṭī, al-Itqān, ch. on collection and arrangement",
    en: ["What is the established position on the order of the verses within each surah?", ["It was fixed by the Prophet's instruction, by consensus", "It was arranged by the ijtihād of Zayd ibn Thābit", "It follows the chronological order of revelation", "It was decided by vote in ʿUthmān's committee"], "Al-Zarkashī and al-Suyūṭī report consensus that the order of verses is tawqīfī: the Prophet told the scribes where to place each verse. Revelation order and verse order often differ."],
    de: ["Welche Position gilt hinsichtlich der Reihenfolge der Verse innerhalb jeder Sure als gesichert?", ["Sie wurde auf Anweisung des Propheten festgelegt, nach Konsens", "Sie wurde durch den ijtihād Zayd ibn Thābits geordnet", "Sie folgt der zeitlichen Reihenfolge der Offenbarung", "Sie wurde im Komitee ʿUthmāns per Abstimmung entschieden"], "Al-Zarkashī und al-Suyūṭī berichten Konsens, dass die Versfolge tawqīfī ist: Der Prophet sagte den Schreibern, wohin jeder Vers gehört. Offenbarungsfolge und Versfolge weichen oft voneinander ab."],
    ar: ["ما القول المستقر في ترتيب الآيات داخل السور؟", ["أنه توقيفي بأمر النبي بالإجماع", "أنه كان باجتهاد زيد بن ثابت وحده", "أنه على ترتيب نزول الآيات زمنيًّا", "أنه قُرّر بالتصويت في لجنة عثمان"], "نقل الزركشي والسيوطي الإجماع على أن ترتيب الآيات توقيفي، فكان النبي صلى الله عليه وسلم يقول: ضعوا هذه الآية في موضع كذا. وترتيب النزول يخالف ترتيب التلاوة كثيرًا."] },

  { id: "ulc-030", s: "ulum", g: 3, d: 4, t: ["surah-order", "tawqifi"], src: "al-Suyūṭī, al-Itqān fī ʿUlūm al-Qurʾān, ch. on collection and arrangement; al-Zarkashī, al-Burhān, ch. on the order of surahs",
    en: ["Which statement correctly describes the scholars' views on the order of the surahs?", ["Views differ: tawqīfī, Companions' ijtihād, or mostly tawqīfī with exceptions", "All scholars agree it was by ijtihād, unlike the order of verses within surahs", "All scholars agree it follows the chronological order of revelation", "All scholars agree Jibrīl fixed it in the final review in Ramaḍān"], "Unlike verse order, the order of surahs is disputed: one view holds it was fixed by the Prophet, another (attributed to Mālik and, in one statement, al-Bāqillānī) that the Companions arranged it by ijtihād, and a third that most was fixed with a few surahs left to them."],
    de: ["Welche Aussage beschreibt die Ansichten der Gelehrten über die Reihenfolge der Suren korrekt?", ["Umstritten: tawqīfī, ijtihād der Gefährten oder überwiegend tawqīfī mit Ausnahmen", "Alle sind sich einig: ijtihād, anders als die Versfolge innerhalb der Suren", "Alle sind sich einig: Sie folgt der zeitlichen Reihenfolge der Offenbarung", "Alle sind sich einig: Jibrīl legte sie bei der letzten Durchsicht im Ramaḍān fest"], "Anders als die Versfolge ist die Surenfolge umstritten: Eine Ansicht hält sie für vom Propheten festgelegt, eine andere (Mālik und in einer Äußerung al-Bāqillānī zugeschrieben) für ijtihād der Gefährten, eine dritte für größtenteils festgelegt, wobei einige Suren ihnen überlassen blieben."],
    ar: ["ما العبارة الصحيحة في بيان أقوال العلماء في ترتيب السور؟", ["قيل توقيفي، وقيل باجتهاد الصحابة، وقيل أكثره توقيفي إلا قليلًا", "اتفق العلماء على أنه اجتهادي بخلاف ترتيب الآيات في السور", "اتفق العلماء على أنه على ترتيب النزول الزمني", "اتفق العلماء على أن جبريل رتّبه في العرضة الأخيرة في رمضان"], "ترتيب السور مختلف فيه بخلاف ترتيب الآيات: فقيل توقيفي، وقيل باجتهاد الصحابة وهو منسوب إلى مالك والقاضي أبي بكر الباقلاني في أحد قوليه، وقيل بعضه توقيفي وبعضه باجتهادهم."] },

  { id: "ulc-031", s: "ulum", g: 3, d: 3, t: ["surah-order", "companion-mushafs"], src: "al-Suyūṭī, al-Itqān fī ʿUlūm al-Qurʾān, ch. on collection and arrangement",
    en: ["What evidence did those who held that the order of surahs was set by the Companions' ijtihād cite?", ["Personal copies of Ibn Masʿūd and Ubayy had different surah orders", "The Companions disagreed on the order of verses in al-Baqara", "The Prophet never recited more than one surah in a single prayer", "Zayd ibn Thābit stated that he had arranged the surahs himself"], "Al-Suyūṭī notes that the private copies of Companions such as ʿAlī, Ubayy and Ibn Masʿūd had different surah orders before ʿUthmān's copies, which suggests the order was not fixed by explicit instruction."],
    de: ["Welchen Beleg führten diejenigen an, die die Surenfolge auf den ijtihād der Gefährten zurückführten?", ["Die Abschriften Ibn Masʿūds und Ubayys hatten andere Surenfolgen", "Die Gefährten waren uneins über die Versfolge in al-Baqara", "Der Prophet rezitierte in einem Gebet nie mehr als eine Sure", "Zayd ibn Thābit erklärte, er habe die Suren selbst geordnet"], "Al-Suyūṭī weist darauf hin, dass die privaten Abschriften von Gefährten wie ʿAlī, Ubayy und Ibn Masʿūd vor ʿUthmāns Abschriften unterschiedliche Surenfolgen hatten, was darauf hindeutet, dass die Folge nicht ausdrücklich angeordnet war."],
    ar: ["بمَ استدل القائلون بأن ترتيب السور كان باجتهاد الصحابة؟", ["باختلاف ترتيب السور في مصاحف ابن مسعود وأُبيّ", "باختلاف الصحابة في ترتيب آيات سورة البقرة", "بأن النبي لم يقرأ في صلاة واحدة أكثر من سورة", "بتصريح زيد بن ثابت بأنه رتّب السور بنفسه"], "ذكر السيوطي أن مصاحف بعض الصحابة كعلي وأُبيّ وابن مسعود كانت مختلفة في ترتيب السور قبل المصاحف العثمانية، فدل ذلك عندهم على أنه لم يكن بتوقيف صريح."] },

  { id: "ulc-032", s: "ulum", g: 4, d: 4, t: ["surah-order", "basmala"], src: "al-Tirmidhī, Jāmiʿ, Abwāb al-Tafsīr, on Sūrat al-Tawba; al-Suyūṭī, al-Itqān, ch. on collection and arrangement",
    en: ["In the report in which Ibn ʿAbbās asked ʿUthmān why he had placed two surahs side by side without a basmala line between them, which surahs were meant?", ["al-Anfāl and al-Tawba", "al-Baqara and Āl ʿImrān", "al-Ḍuḥā and al-Sharḥ", "al-Falaq and al-Nās"], "ʿUthmān answered that the Prophet died without making clear whether al-Tawba belonged to al-Anfāl, and because their contents were similar he put them together without writing a basmala line. Scholars cite this report in the debate on whether surah order is tawqīfī."],
    de: ["In dem Bericht, in dem Ibn ʿAbbās ʿUthmān fragte, warum er zwei Suren ohne Basmala-Zeile dazwischen nebeneinandergestellt habe, um welche Suren ging es?", ["al-Anfāl und al-Tawba", "al-Baqara und Āl ʿImrān", "al-Ḍuḥā und al-Sharḥ", "al-Falaq und al-Nās"], "ʿUthmān antwortete, der Prophet sei gestorben, ohne klarzustellen, ob al-Tawba zu al-Anfāl gehöre; da ihr Inhalt ähnlich sei, habe er sie ohne Basmala-Zeile zusammengestellt. Gelehrte führen diesen Bericht in der Debatte an, ob die Surenfolge tawqīfī ist."],
    ar: ["في الأثر الذي سأل فيه ابنُ عباس عثمانَ عن قرنه بين سورتين دون أن يكتب بينهما سطر البسملة، ما السورتان؟", ["الأنفال والتوبة", "البقرة وآل عمران", "الضحى والشرح", "الفلق والناس"], "أجاب عثمان بأن النبي صلى الله عليه وسلم قُبض ولم يبيّن أن براءة من الأنفال، وكانت قصتها شبيهة بقصتها فقرن بينهما ولم يكتب سطر البسملة. ويُستشهد بهذا الأثر في الخلاف في كون ترتيب السور توقيفيًّا."] },

  { id: "ulc-033", s: "ulum", g: 1, d: 1, t: ["quran-divisions", "ajza"], src: "al-Suyūṭī, al-Itqān fī ʿUlūm al-Qurʾān, ch. on the number of surahs, verses and words",
    en: ["Into how many parts (ajzāʾ) is the muṣḥaf commonly divided for recitation?", ["Thirty", "Sixty", "Seven", "Forty"], "The common division is into thirty ajzāʾ, each of which is made of two aḥzāb, giving sixty aḥzāb. This makes it easy to complete the Quran in a month."],
    de: ["In wie viele Teile (ajzāʾ) wird der Muṣḥaf für die Rezitation üblicherweise eingeteilt?", ["Dreißig", "Sechzig", "Sieben", "Vierzig"], "Die übliche Einteilung umfasst dreißig ajzāʾ, die jeweils aus zwei aḥzāb bestehen, also sechzig aḥzāb. So lässt sich der Koran leicht in einem Monat vollständig rezitieren."],
    ar: ["إلى كم جزءًا يُقسَّم المصحف عادةً للتلاوة؟", ["ثلاثين جزءًا", "ستين جزءًا", "سبعة أجزاء", "أربعين جزءًا"], "التقسيم المشهور ثلاثون جزءًا، كل جزء حزبان، فتكون الأحزاب ستين، وهذا ييسّر ختم القرآن في شهر."] },

  { id: "ulc-034", s: "ulum", g: 2, d: 2, t: ["quran-divisions", "surah-groups"], src: "al-Suyūṭī, al-Itqān fī ʿUlūm al-Qurʾān, ch. on the number of surahs, verses and words; al-Zarkashī, al-Burhān",
    en: ["What name is given to the group of shorter surahs at the end of the muṣḥaf?", ["al-Mufaṣṣal", "al-Miʾūn", "al-Sabʿ al-Ṭiwāl", "al-Mathānī"], "Al-Mufaṣṣal is the last group, so called because of the many separations between its surahs by the basmala. Al-Sabʿ al-Ṭiwāl are the long surahs at the beginning, al-Miʾūn those of about a hundred verses, and al-Mathānī those after them."],
    de: ["Welchen Namen trägt die Gruppe der kürzeren Suren am Ende des Muṣḥaf?", ["al-Mufaṣṣal", "al-Miʾūn", "al-Sabʿ al-Ṭiwāl", "al-Mathānī"], "Al-Mufaṣṣal ist die letzte Gruppe, so genannt wegen der vielen Trennungen zwischen ihren Suren durch die Basmala. Al-Sabʿ al-Ṭiwāl sind die langen Suren am Anfang, al-Miʾūn die mit etwa hundert Versen und al-Mathānī die darauf folgenden."],
    ar: ["ما اسم مجموعة السور القصيرة في آخر المصحف؟", ["المفصَّل", "المئون", "السبع الطوال", "المثاني"], "المفصَّل آخر أقسام السور، سُمّي بذلك لكثرة الفصل بين سوره بالبسملة. والسبع الطوال في أول المصحف، والمئون ما يقارب مئة آية، والمثاني ما يليها."] },

  { id: "ulc-035", s: "ulum", g: 4, d: 5, t: ["quran-divisions", "surah-groups", "hizb-of-companions"], src: "Abū Dāwūd, Sunan, Kitāb al-Ṣalāt, on dividing the recitation (report of Aws ibn Ḥudhayfa); al-Suyūṭī, al-Itqān",
    en: ["In the report of Aws ibn Ḥudhayfa (Sunan Abī Dāwūd), the Companions divided their recitation into groups of 3, 5, 7, 9, 11 and 13 surahs, then the mufaṣṣal. Counting from al-Baqara, with which surah does the final portion begin?", ["Qāf", "al-Ḥujurāt", "al-Raḥmān", "al-Mulk"], "Three, five, seven, nine, eleven and thirteen surahs make 48 surahs after al-Fātiḥa, ending with al-Ḥujurāt (49), so the last portion starts with Qāf (50). Al-Ḥujurāt and other surahs are named in other views on where the mufaṣṣal begins."],
    de: ["Im Bericht des Aws ibn Ḥudhayfa (Sunan Abī Dāwūd) teilten die Gefährten ihre Rezitation in Gruppen von 3, 5, 7, 9, 11 und 13 Suren, dann den mufaṣṣal. Mit welcher Sure beginnt, von al-Baqara an gezählt, der letzte Teil?", ["Qāf", "al-Ḥujurāt", "al-Raḥmān", "al-Mulk"], "Drei, fünf, sieben, neun, elf und dreizehn Suren ergeben 48 Suren nach al-Fātiḥa bis einschließlich al-Ḥujurāt (49); der letzte Teil beginnt also mit Qāf (50). Al-Ḥujurāt und andere Suren werden in anderen Ansichten über den Beginn des mufaṣṣal genannt."],
    ar: ["في أثر أوس بن حذيفة عند أبي داود أن الصحابة كانوا يحزّبون القرآن: ثلاثًا وخمسًا وسبعًا وتسعًا وإحدى عشرة وثلاث عشرة ثم حزب المفصَّل. بالعدّ من البقرة، بأيّ سورة يبدأ الحزب الأخير؟", ["ق", "الحجرات", "الرحمن", "الملك"], "مجموع ثلاث وخمس وسبع وتسع وإحدى عشرة وثلاث عشرة ثمانٍ وأربعون سورة بعد الفاتحة تنتهي بالحجرات (49)، فيبدأ حزب المفصَّل بسورة ق (50). وذُكرت الحجرات وغيرها في أقوال أخرى في أول المفصَّل."] },

  // ---- naskh ----
  { id: "ulc-036", s: "ulum", g: 1, d: 2, t: ["naskh", "naskh-definition"], src: "al-Zarkashī, al-Burhān fī ʿUlūm al-Qurʾān, ch. on abrogation",
    en: ["What does the word naskh mean linguistically?", ["Removal or copying over", "Explanation or clarification", "Addition or increase", "Repetition or emphasis"], "Linguistically, naskh is used for removal (as the sun removes the shade) and for transferring or copying (as in copying a book). The technical meaning in uṣūl builds on the sense of removal."],
    de: ["Was bedeutet das Wort naskh sprachlich?", ["Beseitigung oder Abschrift", "Erklärung oder Verdeutlichung", "Hinzufügung oder Vermehrung", "Wiederholung oder Bekräftigung"], "Sprachlich wird naskh für Beseitigen gebraucht (wie die Sonne den Schatten beseitigt) und für Übertragen oder Abschreiben (wie beim Abschreiben eines Buches). Die Fachbedeutung in den uṣūl knüpft an die Bedeutung des Beseitigens an."],
    ar: ["ما معنى النسخ في اللغة؟", ["الإزالة والنقل", "البيان والتوضيح", "الزيادة والنماء", "التكرار والتأكيد"], "يُطلق النسخ لغةً على الإزالة كقولهم: نسخت الشمس الظل، وعلى النقل كقولهم: نسخت الكتاب. والمعنى الاصطلاحي مبني على معنى الإزالة."] },

  { id: "ulc-037", s: "ulum", g: 2, d: 2, t: ["naskh", "naskh-definition"], src: "al-Zarkashī, al-Burhān, ch. on abrogation; al-Zurqānī, Manāhil al-ʿIrfān, ch. on abrogation",
    en: ["Which is the standard technical definition of naskh?", ["Lifting a sharʿī ruling by a later sharʿī proof", "Limiting a general word to some of its individuals", "Explaining an ambiguous verse by a clearer one", "Restricting an unrestricted word by a description"], "Naskh is the lifting of a sharʿī ruling by a sharʿī proof that comes later. Limiting a general word is takhṣīṣ, restricting an unrestricted word is taqyīd, and explaining an ambiguous text is bayān."],
    de: ["Welche ist die übliche Fachdefinition von naskh?", ["Aufhebung einer Scharia-Regelung durch einen späteren Scharia-Beleg", "Beschränkung eines allgemeinen Wortes auf einige seiner Einzelfälle", "Erklärung eines mehrdeutigen Verses durch einen klareren", "Einschränkung eines unbeschränkten Wortes durch eine Eigenschaft"], "Naskh ist die Aufhebung einer Scharia-Regelung durch einen später kommenden Scharia-Beleg. Die Beschränkung eines allgemeinen Wortes ist takhṣīṣ, die Einschränkung eines unbeschränkten Wortes taqyīd, die Erklärung eines mehrdeutigen Textes bayān."],
    ar: ["ما التعريف الاصطلاحي المشهور للنسخ؟", ["رفع الحكم الشرعي بدليل شرعي متأخر", "قصر العام على بعض أفراده", "تفسير الآية المجملة بآية أوضح منها", "تقييد اللفظ المطلق بوصف"], "النسخ رفع الحكم الشرعي بدليل شرعي متراخٍ عنه. أما قصر العام على بعض أفراده فتخصيص، وتقييد المطلق تقييد، وبيان المجمل بيان."] },

  { id: "ulc-038", s: "ulum", g: 1, d: 2, t: ["naskh", "naskh-evidence"], v: "2:106", src: "Ibn Kathīr, Tafsīr al-Qurʾān al-ʿAẓīm, on 2:106",
    en: ["The verse shown is a principal proof for which concept in ʿulūm al-Qurʾān?", ["Naskh (abrogation)", "Iʿjāz (inimitability)", "Muḥkam and mutashābih", "ʿĀmm and khāṣṣ"], "The verse speaks of God replacing a verse with one better or like it, and scholars such as Ibn Kathīr cite it as a main proof that abrogation occurs in the Sharīʿa."],
    de: ["Der gezeigte Vers ist ein Hauptbeleg für welchen Begriff der ʿulūm al-Qurʾān?", ["Naskh (Abrogation)", "Iʿjāz (Unnachahmlichkeit)", "Muḥkam und mutashābih", "ʿĀmm und khāṣṣ"], "Der Vers spricht davon, dass Gott einen Vers durch einen besseren oder gleichwertigen ersetzt; Gelehrte wie Ibn Kathīr führen ihn als Hauptbeleg dafür an, dass es in der Scharia Abrogation gibt."],
    ar: ["الآية المعروضة من أشهر الأدلة على أيّ مبحث من مباحث علوم القرآن؟", ["النسخ", "الإعجاز", "المحكم والمتشابه", "العام والخاص"], "تذكر الآية أن الله يأتي بخير من الآية المنسوخة أو مثلها، فاستدل بها العلماء كابن كثير على وقوع النسخ في الشريعة."] },

  { id: "ulc-039", s: "ulum", g: 2, d: 3, t: ["naskh", "naskh-types"], src: "al-Suyūṭī, al-Itqān fī ʿUlūm al-Qurʾān, ch. on abrogating and abrogated",
    en: ["What is the name of the category in which the text of a verse is still recited but its ruling no longer applies?", ["Abrogation of the ruling without the recitation", "Abrogation of the recitation without the ruling", "Abrogation of both ruling and recitation", "Specification of the ruling without abrogation"], "Al-Suyūṭī lists three kinds: ruling and recitation both abrogated, ruling abrogated while recitation remains, and recitation abrogated while the ruling remains. The described case is the second, and most books on naskh deal mainly with it."],
    de: ["Wie heißt die Kategorie, bei der der Wortlaut eines Verses weiter rezitiert wird, seine Regelung aber nicht mehr gilt?", ["Abrogation der Regelung ohne den Wortlaut", "Abrogation des Wortlauts ohne die Regelung", "Abrogation von Regelung und Wortlaut", "Spezifizierung der Regelung ohne Abrogation"], "Al-Suyūṭī nennt drei Arten: Regelung und Wortlaut abrogiert, Regelung abrogiert bei bleibendem Wortlaut, Wortlaut abrogiert bei bleibender Regelung. Der beschriebene Fall ist der zweite, und die meisten Bücher über naskh behandeln vor allem ihn."],
    ar: ["ما اسم القسم الذي تبقى فيه تلاوة الآية ويُرفع حكمها؟", ["نسخ الحكم دون التلاوة", "نسخ التلاوة دون الحكم", "نسخ الحكم والتلاوة معًا", "تخصيص الحكم دون نسخ"], "ذكر السيوطي ثلاثة أقسام: ما نُسخ حكمه وتلاوته، وما نُسخ حكمه وبقيت تلاوته، وما نُسخت تلاوته وبقي حكمه. والمسؤول عنه هو الثاني، وعليه أكثر كتب الناسخ والمنسوخ."] },

  { id: "ulc-040", s: "ulum", g: 3, d: 3, t: ["naskh", "naskh-conditions"], src: "al-Zarkashī, al-Burhān, ch. on abrogation; al-Zurqānī, Manāhil al-ʿIrfān, ch. on abrogation",
    en: ["According to the majority, which kind of text cannot be subject to abrogation?", ["A pure report of a past event or a matter of belief", "A command addressed to the believers to perform an act", "A prohibition of an act that was previously allowed", "A permission granted for a limited period of time"], "Naskh applies to rulings (commands, prohibitions, permissions). A pure report cannot be abrogated, because abrogating it would mean declaring a true report false; matters of belief likewise do not change."],
    de: ["Welche Art von Text kann nach Ansicht der Mehrheit nicht abrogiert werden?", ["Ein reiner Bericht über Vergangenes oder eine Glaubensfrage", "Ein an die Gläubigen gerichteter Befehl zu einer Handlung", "Ein Verbot einer Handlung, die vorher erlaubt war", "Eine für einen begrenzten Zeitraum gewährte Erlaubnis"], "Naskh betrifft Regelungen (Gebote, Verbote, Erlaubnisse). Ein reiner Bericht kann nicht abrogiert werden, da dies hieße, einen wahren Bericht für falsch zu erklären; auch Glaubensinhalte ändern sich nicht."],
    ar: ["ما النص الذي لا يدخله النسخ عند الجمهور؟", ["الخبر المحض عن واقعة ماضية أو مسألة اعتقادية", "الأمر الموجّه إلى المؤمنين بفعل شيء", "النهي عن فعل كان مباحًا من قبل", "الإباحة الممنوحة لمدة محددة من الزمن"], "النسخ يدخل الأحكام من أمر ونهي وإباحة، ولا يدخل الخبر المحض لأن نسخه يقتضي تكذيب الخبر، وكذلك أصول الاعتقاد لا تتبدل."] },

  { id: "ulc-041", s: "ulum", g: 3, d: 4, t: ["naskh", "naskh-conditions"], src: "al-Zurqānī, Manāhil al-ʿIrfān, ch. on abrogation; al-Shawkānī, Irshād al-Fuḥūl, ch. on abrogation",
    en: ["When may a scholar judge one text to be abrogated by another?", ["When they truly conflict, cannot be reconciled and the later one is known", "Whenever a later verse gives a more detailed ruling on the matter", "Whenever the earlier verse was revealed in Mecca before the Hijra", "Whenever a later scholar finds the earlier ruling hard to apply"], "Abrogation is not presumed: the two texts must genuinely conflict, reconciliation must be impossible, and which came later must be known from a reliable proof. A more detailed later text is usually explanation or specification, not abrogation."],
    de: ["Wann darf ein Gelehrter einen Text als durch einen anderen abrogiert beurteilen?", ["Wenn sie sich wirklich widersprechen, nicht vereinbar sind und der spätere bekannt ist", "Immer wenn ein späterer Vers eine ausführlichere Regelung zur Sache gibt", "Immer wenn der frühere Vers vor der Hidschra in Mekka offenbart wurde", "Immer wenn ein späterer Gelehrter die frühere Regelung schwer anwendbar findet"], "Abrogation wird nicht vermutet: Die beiden Texte müssen sich wirklich widersprechen, eine Vereinbarung muss unmöglich sein, und welcher später kam, muss durch einen verlässlichen Beleg bekannt sein. Ein ausführlicherer späterer Text ist meist Erklärung oder Spezifizierung, nicht Abrogation."],
    ar: ["متى يجوز للعالم أن يحكم بأن نصًّا منسوخ بنص آخر؟", ["إذا تعارضا حقيقةً وتعذّر الجمع بينهما وعُلم المتأخر منهما", "كلما جاءت آية متأخرة بحكم أكثر تفصيلًا في المسألة", "كلما كانت الآية المتقدمة نازلة بمكة قبل الهجرة", "كلما رأى عالم متأخر أن الحكم الأول يشق تطبيقه"], "لا يُصار إلى النسخ بالاحتمال، بل يُشترط التعارض الحقيقي وتعذّر الجمع ومعرفة المتأخر بدليل صحيح. أما النص المتأخر المفصِّل فهو في الغالب بيان أو تخصيص لا نسخ."] },

  { id: "ulc-042", s: "ulum", g: 3, d: 4, t: ["naskh", "naskh-examples"], v: "58:12", src: "Ibn Kathīr, Tafsīr al-Qurʾān al-ʿAẓīm, on 58:12–13; al-Suyūṭī, al-Itqān, ch. on abrogating and abrogated",
    en: ["The command in the verse shown (giving charity before a private consultation with the Prophet) is commonly cited by scholars as an example of what?", ["A ruling lifted by the next verse while its recitation remains", "A recitation removed from the muṣḥaf while its ruling remains", "A general ruling that was later specified by the Sunna", "An unrestricted ruling that was restricted by a description"], "Most mufassirūn hold that the duty of charity before consultation was lifted by the following verse (58:13), while the verse is still recited. It is among the examples al-Suyūṭī accepts in his short list of abrogated verses."],
    de: ["Das Gebot im gezeigten Vers (Almosen vor einem vertraulichen Gespräch mit dem Propheten) wird von Gelehrten häufig als Beispiel wofür genannt?", ["Eine durch den nächsten Vers aufgehobene Regelung bei bleibendem Wortlaut", "Ein aus dem Muṣḥaf entfernter Wortlaut bei bleibender Regelung", "Eine allgemeine Regelung, die später durch die Sunna spezifiziert wurde", "Eine unbeschränkte Regelung, die durch eine Eigenschaft eingeschränkt wurde"], "Die meisten Exegeten halten die Pflicht zum Almosen vor dem Gespräch für durch den folgenden Vers (58:13) aufgehoben, während der Vers weiter rezitiert wird. Er gehört zu den Beispielen, die al-Suyūṭī in seiner kurzen Liste abrogierter Verse anerkennt."],
    ar: ["الأمر في الآية المعروضة بتقديم الصدقة بين يدي مناجاة الرسول يذكره العلماء عادةً مثالًا على ماذا؟", ["حكم رُفع بالآية التي بعدها مع بقاء تلاوته", "تلاوة رُفعت من المصحف مع بقاء حكمها", "حكم عام خصّصته السنة بعد ذلك", "حكم مطلق قُيّد بوصف في آية أخرى"], "ذهب أكثر المفسرين إلى أن وجوب تقديم الصدقة قبل المناجاة نُسخ بالآية التي بعدها (58:13) مع بقاء التلاوة، وهو من الأمثلة التي أقرّها السيوطي في قائمته المختصرة للمنسوخ."] },

  { id: "ulc-043", s: "ulum", g: 4, d: 5, t: ["naskh", "naskh-examples"], v: "2:240", src: "al-Bukhārī, Ṣaḥīḥ, Kitāb al-Tafsīr, on 2:240; Ibn Kathīr, Tafsīr al-Qurʾān al-ʿAẓīm, on 2:240",
    en: ["Which statement correctly describes the scholars' positions on the verse shown, about provision for a widow for a full year?", ["Most: abrogated by 2:234; some, such as Mujāhid, reconciled the two verses", "All scholars agree that 2:234 was itself abrogated by this verse", "All scholars agree that it was never part of the recited Quran", "Most: it abrogated the waiting period of four months and ten days"], "The majority held that the year's provision was abrogated by the waiting period of four months and ten days in 2:234 (and the shares of inheritance). Al-Bukhārī reports that Mujāhid instead saw the year as a recommended bequest beyond the obligatory waiting period, so the verses do not conflict."],
    de: ["Welche Aussage beschreibt die Positionen der Gelehrten zum gezeigten Vers über die Versorgung einer Witwe für ein volles Jahr korrekt?", ["Meist: durch 2:234 abrogiert; einige wie Mujāhid vereinbarten beide Verse", "Alle Gelehrten: 2:234 wurde selbst durch diesen Vers abrogiert", "Alle Gelehrten: Er gehörte zu keiner Zeit zum rezitierten Koran", "Meist: Er abrogierte die Wartezeit von vier Monaten und zehn Tagen"], "Die Mehrheit hielt die Jahresversorgung für abrogiert durch die Wartezeit von vier Monaten und zehn Tagen in 2:234 (und die Erbanteile). Al-Bukhārī berichtet, dass Mujāhid das Jahr dagegen als empfohlene Verfügung über die Pflichtwartezeit hinaus sah, sodass sich die Verse nicht widersprechen."],
    ar: ["ما العبارة الصحيحة في بيان أقوال العلماء في الآية المعروضة في متاع المتوفى عنها زوجها حولًا كاملًا؟", ["الأكثر: منسوخة بالآية 2:234، وجمع بعضهم كمجاهد بين الآيتين", "اتفقوا على أن الآية 2:234 هي المنسوخة بهذه الآية", "اتفقوا على أنها لم تكن قط من القرآن المتلو", "الأكثر: أنها ناسخة لعدة أربعة أشهر وعشر"], "ذهب الجمهور إلى أن متاع الحول نُسخ بعدة أربعة أشهر وعشر في الآية 2:234 وبآية المواريث، وروى البخاري عن مجاهد أن الحول وصية مستحبة زائدة على العدة الواجبة فلا تعارض بين الآيتين."] },

  { id: "ulc-044", s: "ulum", g: 3, d: 4, t: ["naskh", "naskh-examples", "verse-order"], v: "2:240", src: "al-Bukhārī, Ṣaḥīḥ, Kitāb al-Tafsīr, on 2:240",
    en: ["Ibn al-Zubayr asked ʿUthmān why he still wrote the verse shown in the muṣḥaf although another verse had abrogated it. What did ʿUthmān answer?", ["That he would not move anything of the Quran from its place", "That the verse had in fact never been abrogated at all", "That the Prophet had ordered it to be written down twice", "That Zayd ibn Thābit had insisted on including it there"], "Al-Bukhārī reports ʿUthmān's reply that he would not change anything of it from its place. The report shows that abrogated rulings could remain in the recited text and that the placement of verses was not a matter of personal choice."],
    de: ["Ibn al-Zubayr fragte ʿUthmān, warum er den gezeigten Vers noch in den Muṣḥaf schreibe, obwohl ein anderer Vers ihn abrogiert habe. Was antwortete ʿUthmān?", ["Er werde nichts vom Koran von seiner Stelle verrücken", "Der Vers sei überhaupt nicht abrogiert worden", "Der Prophet habe befohlen, ihn zweimal zu schreiben", "Zayd ibn Thābit habe auf seiner Aufnahme bestanden"], "Al-Bukhārī überliefert ʿUthmāns Antwort, er werde nichts davon von seiner Stelle ändern. Der Bericht zeigt, dass abrogierte Regelungen im rezitierten Text bleiben konnten und die Platzierung der Verse keine persönliche Entscheidung war."],
    ar: ["سأل ابنُ الزبير عثمانَ: لِمَ تكتب الآية المعروضة في المصحف وقد نسختها الآية الأخرى؟ فبمَ أجاب؟", ["بأنه لا يغيّر شيئًا من القرآن عن مكانه", "بأن الآية لم تُنسخ أصلًا", "بأن النبي أمر بكتابتها مرتين", "بأن زيد بن ثابت أصرّ على إثباتها"], "روى البخاري أن عثمان قال: يا ابن أخي، لا أغيّر شيئًا منه من مكانه. ويدل ذلك على أن الآية قد يُنسخ حكمها وتبقى تلاوتها، وأن مواضع الآيات ليست بالاختيار."] },

  { id: "ulc-045", s: "ulum", g: 3, d: 4, t: ["naskh", "naskh-types", "naskh-examples"], src: "al-Bukhārī, Ṣaḥīḥ, Kitāb al-Ḥudūd, report of ʿUmar on stoning; al-Suyūṭī, al-Itqān, ch. on abrogating and abrogated",
    en: ["Which example do scholars commonly give for abrogation of the recitation while the ruling remains?", ["The verse of stoning mentioned by ʿUmar in his sermon", "The verse of the widow's provision for a full year", "The verse requiring charity before consultation", "The verse on the ratio of fighters in al-Anfāl"], "ʿUmar stated in a sermon reported by al-Bukhārī and Muslim that a verse on stoning had been revealed and acted upon; its wording is not in the muṣḥaf but the ruling remained. The other three are examples given for abrogation of a ruling while the recitation remains."],
    de: ["Welches Beispiel nennen Gelehrte häufig für die Abrogation des Wortlauts bei bleibender Regelung?", ["Den Vers über die Steinigung, den ʿUmar in seiner Predigt erwähnte", "Den Vers über die Versorgung der Witwe für ein volles Jahr", "Den Vers, der Almosen vor dem vertraulichen Gespräch verlangte", "Den Vers über das Zahlenverhältnis der Kämpfer in al-Anfāl"], "ʿUmar erklärte in einer bei al-Bukhārī und Muslim überlieferten Predigt, dass ein Vers über die Steinigung offenbart und danach gehandelt worden sei; sein Wortlaut steht nicht im Muṣḥaf, die Regelung blieb bestehen. Die anderen drei werden als Beispiele für die Abrogation einer Regelung bei bleibendem Wortlaut genannt."],
    ar: ["ما المثال الذي يذكره العلماء عادةً لنسخ التلاوة مع بقاء الحكم؟", ["آية الرجم التي ذكرها عمر في خطبته", "آية متاع المتوفى عنها زوجها حولًا", "آية تقديم الصدقة بين يدي المناجاة", "آية نسبة المقاتلين في سورة الأنفال"], "ذكر عمر في خطبته التي رواها البخاري ومسلم أن آية الرجم أُنزلت وعُمل بها، فرُفع لفظها من المصحف وبقي حكمها. أما الثلاثة الأخرى فيُمثَّل بها لنسخ الحكم مع بقاء التلاوة."] },

  { id: "ulc-046", s: "ulum", g: 4, d: 5, t: ["naskh", "naskh-types", "naskh-examples"], src: "Muslim, Ṣaḥīḥ, Kitāb al-Raḍāʿ, report of ʿĀʾisha; al-Suyūṭī, al-Itqān, ch. on abrogating and abrogated",
    en: ["In ʿĀʾisha's report in Ṣaḥīḥ Muslim about the number of sucklings, the 'ten known sucklings' are commonly cited as an example of which kind of abrogation?", ["Abrogation of both the recitation and the ruling", "Abrogation of the ruling while the recitation remains", "Abrogation of the recitation while the ruling remains", "Abrogation of the Sunna by the Quran"], "ʿĀʾisha reported that ten sucklings had been revealed and were then abrogated by five; the ten are no longer recited nor acted upon, so they serve as the standard example of both being abrogated. How to treat the five is a separate fiqh discussion in which the schools differ."],
    de: ["Im Bericht ʿĀʾishas in Ṣaḥīḥ Muslim über die Zahl der Stillvorgänge werden die „zehn bekannten Stillvorgänge“ häufig als Beispiel für welche Art von Abrogation genannt?", ["Abrogation von Wortlaut und Regelung", "Abrogation der Regelung bei bleibendem Wortlaut", "Abrogation des Wortlauts bei bleibender Regelung", "Abrogation der Sunna durch den Koran"], "ʿĀʾisha berichtete, dass zehn Stillvorgänge offenbart und dann durch fünf abrogiert worden seien; die zehn werden weder rezitiert noch angewandt, daher gelten sie als Standardbeispiel für die Abrogation beider. Wie die fünf zu behandeln sind, ist eine eigene Fiqh-Frage, in der die Schulen auseinandergehen."],
    ar: ["في حديث عائشة في صحيح مسلم عن عدد الرضعات، يُمثَّل بـ«عشر رضعات معلومات» لأيّ نوع من النسخ؟", ["نسخ التلاوة والحكم معًا", "نسخ الحكم مع بقاء التلاوة", "نسخ التلاوة مع بقاء الحكم", "نسخ السنة بالقرآن"], "أخبرت عائشة أنه كان فيما أُنزل عشر رضعات معلومات ثم نُسخن بخمس، فالعشر لا تُتلى ولا يُعمل بها، فهي المثال المشهور لنسخ التلاوة والحكم معًا. أما الخمس فمسألة فقهية مستقلة اختلفت فيها المذاهب."] },

  { id: "ulc-047", s: "ulum", g: 4, d: 5, t: ["naskh", "naskh-by-sunna"], tr: ["shafii", "comparative"], src: "al-Shāfiʿī, al-Risāla, chapter on abrogation; al-Zarkashī, al-Burhān, ch. on abrogation",
    en: ["Which imam is best known for holding that the Quran is abrogated only by the Quran and the Sunna only by the Sunna, a view many later uṣūlīs did not share?", ["al-Shāfiʿī", "Abū Ḥanīfa", "Mālik ibn Anas", "Muḥammad ibn al-Ḥasan al-Shaybānī"], "Al-Shāfiʿī argued in al-Risāla that only the Quran abrogates the Quran, with the Sunna explaining rather than abrogating it. The Ḥanafīs and many others permitted abrogation of the Quran by mutawātir Sunna in principle."],
    de: ["Welcher Imam ist vor allem für die Ansicht bekannt, dass der Koran nur durch den Koran und die Sunna nur durch die Sunna abrogiert wird, eine Ansicht, die viele spätere uṣūlī nicht teilten?", ["al-Shāfiʿī", "Abū Ḥanīfa", "Mālik ibn Anas", "Muḥammad ibn al-Ḥasan al-Shaybānī"], "Al-Shāfiʿī legte in al-Risāla dar, dass nur der Koran den Koran abrogiert und die Sunna ihn erklärt, aber nicht abrogiert. Die Ḥanafiten und viele andere ließen die Abrogation des Korans durch mutawātir-Sunna grundsätzlich zu."],
    ar: ["مَن الإمام المشهور بأن القرآن لا يُنسخ إلا بالقرآن والسنة لا تُنسخ إلا بالسنة، وهو قول خالفه فيه كثير من الأصوليين بعده؟", ["الشافعي", "أبو حنيفة", "مالك بن أنس", "محمد بن الحسن الشيباني"], "قرّر الشافعي في الرسالة أن القرآن لا ينسخه إلا القرآن، وأن السنة مبيّنة له لا ناسخة. وأجاز الحنفية وكثيرون غيرهم نسخ القرآن بالسنة المتواترة من حيث الأصل."] },

  { id: "ulc-048", s: "ulum", g: 4, d: 5, t: ["naskh", "naskh-debate"], src: "al-Rāzī, Mafātīḥ al-Ghayb, on 2:106; al-Zurqānī, Manāhil al-ʿIrfān, ch. on abrogation",
    en: ["Which early scholar is known for denying that any verse of the Quran is abrogated, explaining the usual examples as specification instead?", ["Abū Muslim al-Iṣfahānī", "Abū Jaʿfar al-Naḥḥās", "Abū ʿUbayd al-Qāsim ibn Sallām", "Ibn al-Jawzī"], "Abū Muslim al-Iṣfahānī, a Muʿtazilī mufassir, is regularly cited (for example by al-Rāzī) for denying abrogation within the Quran; the majority rejected his view. Al-Naḥḥās, Abū ʿUbayd and Ibn al-Jawzī all wrote books listing abrogated verses."],
    de: ["Welcher frühe Gelehrte ist dafür bekannt, die Abrogation eines Koranverses zu bestreiten und die üblichen Beispiele stattdessen als Spezifizierung zu erklären?", ["Abū Muslim al-Iṣfahānī", "Abū Jaʿfar al-Naḥḥās", "Abū ʿUbayd al-Qāsim ibn Sallām", "Ibn al-Jawzī"], "Abū Muslim al-Iṣfahānī, ein muʿtazilitischer Exeget, wird regelmäßig (etwa von al-Rāzī) für die Leugnung der Abrogation innerhalb des Korans genannt; die Mehrheit wies seine Ansicht zurück. Al-Naḥḥās, Abū ʿUbayd und Ibn al-Jawzī verfassten Bücher, die abrogierte Verse auflisten."],
    ar: ["مَن العالم المتقدم المعروف بإنكار وقوع النسخ في آيات القرآن، وحمْل الأمثلة المشهورة على التخصيص؟", ["أبو مسلم الأصفهاني", "أبو جعفر النحاس", "أبو عبيد القاسم بن سلام", "ابن الجوزي"], "اشتهر أبو مسلم الأصفهاني المفسر المعتزلي بإنكار النسخ في القرآن، ونقل ذلك عنه الرازي وغيره، وردّ الجمهور قوله. أما النحاس وأبو عبيد وابن الجوزي فقد ألّفوا كتبًا في الناسخ والمنسوخ."] },

  { id: "ulc-049", s: "ulum", g: 4, d: 4, t: ["naskh", "naskh-debate"], src: "Shāh Walī Allāh al-Dihlawī, al-Fawz al-Kabīr fī Uṣūl al-Tafsīr; al-Suyūṭī, al-Itqān, ch. on abrogating and abrogated",
    en: ["Al-Suyūṭī reduced the genuinely abrogated verses to about twenty. To how many did Shāh Walī Allāh al-Dihlawī reduce them in al-Fawz al-Kabīr?", ["Five", "Fifteen", "Seventy", "Over two hundred"], "Shāh Walī Allāh examined al-Suyūṭī's list and accepted abrogation in only five cases, reconciling the rest. Earlier works counted far more because they used naskh in a broader sense."],
    de: ["Al-Suyūṭī reduzierte die tatsächlich abrogierten Verse auf etwa zwanzig. Auf wie viele reduzierte Shāh Walī Allāh al-Dihlawī sie in al-Fawz al-Kabīr?", ["Fünf", "Fünfzehn", "Siebzig", "Über zweihundert"], "Shāh Walī Allāh prüfte al-Suyūṭīs Liste und erkannte nur in fünf Fällen eine Abrogation an, die übrigen vereinbarte er. Frühere Werke zählten weit mehr, weil sie naskh in einem weiteren Sinn verwendeten."],
    ar: ["قصر السيوطي الآيات المنسوخة حقيقةً على نحو عشرين آية. فإلى كم قصرها شاه ولي الله الدهلوي في الفوز الكبير؟", ["خمس آيات", "خمس عشرة آية", "سبعين آية", "أكثر من مئتي آية"], "تتبّع شاه ولي الله قائمة السيوطي فلم يسلّم بالنسخ إلا في خمسة مواضع وجمع بين النصوص في الباقي. وكانت الكتب المتقدمة تعدّ أكثر من ذلك بكثير لأنها استعملت النسخ بمعنى أوسع."] },

  { id: "ulc-050", s: "ulum", g: 3, d: 4, t: ["naskh", "naskh-debate", "takhsis"], src: "al-Shāṭibī, al-Muwāfaqāt, Kitāb al-Adilla, on abrogation; Ibn al-Qayyim, Iʿlām al-Muwaqqiʿīn",
    en: ["Why do early lists of 'abrogated' verses contain far more verses than the lists of later scholars?", ["Early scholars also called specification and restriction naskh", "Later scholars lost many of the earlier reports on abrogation", "Early scholars held every Meccan verse abrogated by Medinan ones", "Later scholars rejected abrogation in the Quran entirely"], "Al-Shāṭibī and Ibn al-Qayyim explain that the Salaf called any lifting or modification of an apparent meaning naskh, including takhṣīṣ, taqyīd and bayān. Later uṣūlīs reserved the term for lifting a ruling, so their lists are much shorter."],
    de: ["Warum enthalten frühe Listen „abrogierter“ Verse weit mehr Verse als die Listen späterer Gelehrter?", ["Frühe Gelehrte nannten auch Spezifizierung und Einschränkung naskh", "Spätere Gelehrte verloren viele frühe Berichte über Abrogation", "Frühe Gelehrte hielten jeden mekkanischen Vers für abrogiert", "Spätere Gelehrte lehnten Abrogation im Koran völlig ab"], "Al-Shāṭibī und Ibn al-Qayyim erklären, dass die Salaf jede Aufhebung oder Abwandlung einer äußeren Bedeutung naskh nannten, einschließlich takhṣīṣ, taqyīd und bayān. Spätere uṣūlī verwendeten den Begriff nur für die Aufhebung einer Regelung, daher sind ihre Listen viel kürzer."],
    ar: ["لماذا تضم قوائم المنسوخ عند المتقدمين آيات أكثر بكثير مما عند المتأخرين؟", ["لأن المتقدمين سمّوا التخصيص والتقييد نسخًا أيضًا", "لأن المتأخرين فقدوا كثيرًا من آثار النسخ", "لأن المتقدمين عدّوا كل آية مكية منسوخة", "لأن المتأخرين أنكروا النسخ في القرآن كليًّا"], "بيّن الشاطبي وابن القيم أن السلف كانوا يسمّون كل رفع أو تغيير لظاهر الحكم نسخًا، فيدخل فيه التخصيص والتقييد والبيان، أما الأصوليون المتأخرون فخصّوه برفع الحكم، فقلّت عندهم المواضع."] },

  { id: "ulc-051", s: "ulum", g: 3, d: 4, t: ["naskh", "takhsis"], src: "al-Zarkashī, al-Burhān, ch. on abrogation; al-Zurqānī, Manāhil al-ʿIrfān, ch. on abrogation",
    en: ["What is the key difference between naskh and takhṣīṣ?", ["Naskh lifts a ruling that applied; takhṣīṣ shows some cases were never meant", "Naskh applies only to Meccan verses; takhṣīṣ applies only to Medinan verses", "Naskh may rest on a weak report; takhṣīṣ requires a mutawātir report", "Naskh affects only the wording; takhṣīṣ affects only the ruling itself"], "In naskh the ruling applied fully and is then lifted from a later time; in takhṣīṣ the general wording is shown never to have been intended for certain individuals. A specifier can also be connected to the text, whereas an abrogating proof must come later."],
    de: ["Was ist der wesentliche Unterschied zwischen naskh und takhṣīṣ?", ["Naskh hebt eine geltende Regelung auf; takhṣīṣ zeigt, dass manche Fälle nie erfasst waren", "Naskh gilt nur für mekkanische Verse, takhṣīṣ nur für medinensische Verse", "Naskh darf auf einem schwachen Bericht beruhen, takhṣīṣ braucht einen mutawātir-Bericht", "Naskh betrifft nur den Wortlaut, takhṣīṣ betrifft nur die Regelung selbst"], "Beim naskh galt die Regelung vollständig und wird ab einem späteren Zeitpunkt aufgehoben; beim takhṣīṣ zeigt sich, dass der allgemeine Wortlaut für bestimmte Einzelfälle nie gemeint war. Ein Spezifizierer kann auch mit dem Text verbunden sein, ein abrogierender Beleg muss später kommen."],
    ar: ["ما الفرق الجوهري بين النسخ والتخصيص؟", ["النسخ رفع للحكم بعد ثبوته، والتخصيص بيان أن بعض الأفراد لم يُرَد أصلًا", "النسخ خاص بالآيات المكية، والتخصيص خاص بالآيات المدنية", "النسخ يكفي فيه الخبر الضعيف، والتخصيص يُشترط فيه المتواتر", "النسخ يتعلق باللفظ وحده، والتخصيص يتعلق بالحكم وحده"], "في النسخ يثبت الحكم لجميع أفراده ثم يُرفع في زمن لاحق، وفي التخصيص يتبيّن أن بعض الأفراد لم يكونوا مرادين باللفظ العام أصلًا. ويجوز أن يكون المخصِّص متصلًا، أما الناسخ فلا بد أن يكون متراخيًا."] },

  // ---- muḥkam and mutashābih ----
  { id: "ulc-052", s: "ulum", g: 1, d: 2, t: ["muhkam-mutashabih"], v: "3:7", src: "Ibn Kathīr, Tafsīr al-Qurʾān al-ʿAẓīm, on 3:7",
    en: ["The verse shown divides the verses of the Book into which two kinds?", ["Muḥkam and mutashābih", "Nāsikh and mansūkh", "ʿĀmm and khāṣṣ", "Muṭlaq and muqayyad"], "The verse states that some verses are muḥkam, the foundation of the Book, and others mutashābih, and warns against those who follow the mutashābih seeking discord. The other pairs are separate topics of ʿulūm al-Qurʾān."],
    de: ["In welche zwei Arten teilt der gezeigte Vers die Verse des Buches ein?", ["Muḥkam und mutashābih", "Nāsikh und mansūkh", "ʿĀmm und khāṣṣ", "Muṭlaq und muqayyad"], "Der Vers sagt, dass manche Verse muḥkam sind, die Grundlage des Buches, und andere mutashābih, und warnt vor denen, die dem mutashābih folgen, um Zwietracht zu suchen. Die anderen Paare sind eigene Themen der ʿulūm al-Qurʾān."],
    ar: ["إلى أيّ قسمين تقسم الآية المعروضة آيات الكتاب؟", ["المحكم والمتشابه", "الناسخ والمنسوخ", "العام والخاص", "المطلق والمقيد"], "نصّت الآية على أن من الكتاب آيات محكمات هن أم الكتاب وأُخر متشابهات، وذمّت من يتبع المتشابه ابتغاء الفتنة. أما بقية الأزواج فمباحث أخرى من علوم القرآن."] },

  { id: "ulc-053", s: "ulum", g: 3, d: 3, t: ["muhkam-mutashabih"], v: "39:23", w: 6, src: "al-Suyūṭī, al-Itqān fī ʿUlūm al-Qurʾān, ch. on muḥkam and mutashābih; Ibn Kathīr, Tafsīr, on 39:23",
    en: ["In the verse shown, the whole Book is described with the highlighted word (mutashābih). In what sense is the whole Quran mutashābih here?", ["Its parts resemble one another in excellence and truth", "Its meanings are unknown to everyone but God", "Its rulings have all been abrogated", "Its wording resembles that of earlier scriptures"], "Scholars distinguish three usages: the whole Quran is muḥkam in the sense of perfected (11:1), the whole is mutashābih in the sense of its parts resembling each other in beauty and truth (this verse), and some verses are muḥkam and others mutashābih in the specific sense of 3:7."],
    de: ["Im gezeigten Vers wird das ganze Buch mit dem hervorgehobenen Wort (mutashābih) beschrieben. In welchem Sinn ist der ganze Koran hier mutashābih?", ["Seine Teile gleichen einander an Vortrefflichkeit und Wahrheit", "Seine Bedeutungen sind allen außer Gott gänzlich unbekannt", "Seine Regelungen sind sämtlich durch spätere Verse abrogiert", "Sein Wortlaut gleicht dem der früheren offenbarten Schriften"], "Gelehrte unterscheiden drei Verwendungen: Der ganze Koran ist muḥkam im Sinne von vollkommen gefügt (11:1), der ganze ist mutashābih in dem Sinne, dass seine Teile einander an Schönheit und Wahrheit gleichen (dieser Vers), und einige Verse sind muḥkam, andere mutashābih im besonderen Sinn von 3:7."],
    ar: ["وُصف الكتاب كله في الآية المعروضة بالكلمة المظللة (متشابهًا). بأيّ معنى كان القرآن كله متشابهًا هنا؟", ["أنه يشبه بعضه بعضًا في الحسن والصدق", "أن معانيه لا يعلمها أحد إلا الله", "أن أحكامه كلها منسوخة", "أن ألفاظه تشبه ألفاظ الكتب السابقة"], "فرّق العلماء بين ثلاثة إطلاقات: القرآن كله محكم بمعنى الإتقان (11:1)، وكله متشابه بمعنى أنه يشبه بعضه بعضًا في الحسن والصدق (هذه الآية)، وبعضه محكم وبعضه متشابه بالمعنى الخاص في آية آل عمران (3:7)."] },

  { id: "ulc-054", s: "ulum", g: 4, d: 5, t: ["muhkam-mutashabih", "waqf-in-3-7"], v: "3:7", w: 32, src: "al-Ṭabarī, Jāmiʿ al-Bayān, on 3:7; al-Zarkashī, al-Burhān, ch. on muḥkam and mutashābih; al-Suyūṭī, al-Itqān",
    en: ["Which statement correctly describes the disagreement about the highlighted word ('and those firmly grounded in knowledge') in the verse shown?", ["Many pause before it, so only God knows; others join it, so the learned know too", "All scholars agree that one must join it to the name of God without pausing", "All scholars agree that the firmly grounded know the reality of every unseen matter", "The disagreement concerns only the vowel of its ending, not its meaning at all"], "Many of the Salaf and the majority pause after the name of God, making 'those firmly grounded' the start of a new sentence; others, such as Mujāhid, join them, so they also know the interpretation. Many later scholars reconcile the views: taʾwīl meaning ultimate reality is known to God alone, while taʾwīl meaning explanation is known to the learned."],
    de: ["Welche Aussage beschreibt die Meinungsverschiedenheit über das hervorgehobene Wort („und die im Wissen fest Gegründeten“) im gezeigten Vers korrekt?", ["Viele pausieren davor, nur Gott weiß es; andere verbinden, auch die Gelehrten wissen es", "Alle Gelehrten verlangen, es ohne Pause mit dem Namen Gottes zu verbinden", "Alle Gelehrten sagen, die fest Gegründeten kennen die Wirklichkeit alles Verborgenen", "Der Streit betrifft nur den Vokal seiner Endung, nicht seine Bedeutung"], "Viele der Salaf und die Mehrheit pausieren nach dem Namen Gottes, sodass „die fest Gegründeten“ einen neuen Satz beginnen; andere, etwa Mujāhid, verbinden, sodass auch sie die Deutung kennen. Viele spätere Gelehrte vereinbaren beides: taʾwīl als letzte Wirklichkeit kennt nur Gott, taʾwīl als Erklärung kennen die Gelehrten."],
    ar: ["ما العبارة الصحيحة في بيان الخلاف في الكلمة المظللة من الآية المعروضة؟", ["يقف كثيرون قبلها فلا يعلمه إلا الله، ويصل آخرون فيعلمه الراسخون", "اتفق العلماء على وجوب وصلها بلفظ الجلالة دون أيّ وقف", "اتفق العلماء على أن الراسخين يعلمون حقائق جميع الأمور الغيبية", "الخلاف في حركة آخرها فقط لا في معناها ولا في الوقف"], "وقف كثير من السلف والجمهور على لفظ الجلالة وجعلوا الراسخين مبتدأً، ووصل آخرون كمجاهد فجعلوهم يعلمون التأويل. وجمع كثير من المتأخرين بأن التأويل بمعنى الحقيقة التي يؤول إليها الأمر لا يعلمه إلا الله، والتأويل بمعنى التفسير يعلمه الراسخون."] },

  { id: "ulc-055", s: "ulum", g: 2, d: 2, t: ["muhkam-mutashabih"], src: "al-Suyūṭī, al-Itqān fī ʿUlūm al-Qurʾān, ch. on muḥkam and mutashābih; al-Zurqānī, Manāhil al-ʿIrfān",
    en: ["In the specific sense of 3:7, which description best fits a muḥkam verse?", ["Its meaning is clear and needs no other text to explain it", "Its ruling has been lifted by a verse revealed later", "It was revealed in Mecca before the Hijra took place", "Its meaning can be known only by a few of the scholars"], "Among the definitions al-Suyūṭī gives, the most common is that the muḥkam is clear in meaning and stands on its own, while the mutashābih admits several meanings or needs to be referred to the muḥkam for its explanation."],
    de: ["Welche Beschreibung passt im besonderen Sinn von 3:7 am besten auf einen muḥkam-Vers?", ["Seine Bedeutung ist klar und braucht keinen anderen Text", "Seine Regelung wurde durch einen späteren Vers aufgehoben", "Er wurde vor der Hidschra in Mekka herabgesandt", "Nur wenige Gelehrte können seine Bedeutung erkennen"], "Unter den Definitionen, die al-Suyūṭī anführt, ist die geläufigste, dass der muḥkam in seiner Bedeutung klar ist und für sich steht, während der mutashābih mehrere Bedeutungen zulässt oder zur Erklärung auf den muḥkam zurückgeführt werden muss."],
    ar: ["بالمعنى الخاص في آية آل عمران (3:7)، أيّ وصف أنسب للآية المحكمة؟", ["ما اتضح معناه فلم يحتج إلى بيان من غيره", "ما نُسخ حكمه بآية نزلت بعده", "ما نزل بمكة قبل هجرة النبي", "ما لا يعرف معناه إلا قلة من العلماء"], "من أشهر ما نقله السيوطي في تعريف المحكم: ما وضح معناه واستقل بنفسه، والمتشابه ما احتمل أوجهًا أو احتاج إلى ردّه إلى المحكم لبيان معناه."] },

  { id: "ulc-056", s: "ulum", g: 4, d: 5, t: ["muhkam-mutashabih", "mutashabih-lafzi"], src: "al-Kirmānī, al-Burhān fī Mutashābih al-Qurʾān; al-Suyūṭī, al-Itqān",
    en: ["Which scholar wrote al-Burhān fī Mutashābih al-Qurʾān (also known as Asrār al-Takrār), on verses that repeat with slight differences in wording?", ["Maḥmūd ibn Ḥamza al-Kirmānī", "Badr al-Dīn al-Zarkashī", "Abū Bakr al-Bāqillānī", "Abū al-Ḥasan al-Wāḥidī"], "Al-Kirmānī's work explains why similar verses differ slightly (mutashābih lafẓī). Al-Zarkashī's al-Burhān fī ʿUlūm al-Qurʾān has a similar title but is a general work on the Quranic sciences."],
    de: ["Welcher Gelehrte verfasste al-Burhān fī Mutashābih al-Qurʾān (auch Asrār al-Takrār genannt) über Verse, die sich mit leichten Abweichungen im Wortlaut wiederholen?", ["Maḥmūd ibn Ḥamza al-Kirmānī", "Badr al-Dīn al-Zarkashī", "Abū Bakr al-Bāqillānī", "Abū al-Ḥasan al-Wāḥidī"], "Al-Kirmānīs Werk erklärt, warum sich ähnliche Verse geringfügig unterscheiden (mutashābih lafẓī). Al-Zarkashīs al-Burhān fī ʿUlūm al-Qurʾān hat einen ähnlichen Titel, ist aber ein allgemeines Werk über die Koranwissenschaften."],
    ar: ["مَن مؤلف كتاب البرهان في متشابه القرآن (ويُعرف بأسرار التكرار) في الآيات المتكررة مع اختلاف يسير في اللفظ؟", ["محمود بن حمزة الكرماني", "بدر الدين الزركشي", "أبو بكر الباقلاني", "أبو الحسن الواحدي"], "كتاب الكرماني في توجيه المتشابه اللفظي وبيان سبب الاختلاف اليسير بين الآيات المتشابهة. أما البرهان في علوم القرآن للزركشي فعنوانه قريب لكنه كتاب جامع في علوم القرآن."] },

  // ---- ʿāmm and khāṣṣ ----
  { id: "ulc-057", s: "ulum", g: 2, d: 2, t: ["amm-khass"], src: "al-Suyūṭī, al-Itqān fī ʿUlūm al-Qurʾān, ch. on general and specific; al-Zurqānī, Manāhil al-ʿIrfān",
    en: ["What is an ʿāmm (general) word in uṣūl and ʿulūm al-Qurʾān?", ["A word covering all individuals it fits, at once and without limit", "A word that refers to one unspecified individual of its kind", "A word that has two or more unrelated meanings in the language", "A word whose meaning is hidden and needs another text to explain it"], "The ʿāmm includes all its individuals together, such as 'the believers'. A word for one unspecified individual is muṭlaq, a word with several meanings is mushtarak, and a word needing explanation is mujmal."],
    de: ["Was ist ein ʿāmm-Wort (allgemeines Wort) in den uṣūl und den ʿulūm al-Qurʾān?", ["Ein Wort, das alle passenden Einzelfälle zugleich und unbegrenzt umfasst", "Ein Wort, das ein unbestimmtes Einzelnes seiner Art bezeichnet", "Ein Wort mit zwei oder mehr unverbundenen Bedeutungen in der Sprache", "Ein Wort, dessen Bedeutung verborgen ist und eines anderen Textes bedarf"], "Das ʿāmm umfasst alle seine Einzelfälle zugleich, etwa „die Gläubigen“. Ein Wort für ein unbestimmtes Einzelnes ist muṭlaq, ein Wort mit mehreren Bedeutungen mushtarak, ein erklärungsbedürftiges Wort mujmal."],
    ar: ["ما اللفظ العام عند الأصوليين وفي علوم القرآن؟", ["اللفظ المستغرق لجميع ما يصلح له دفعة واحدة بلا حصر", "اللفظ الدال على فرد شائع في جنسه", "اللفظ الدال على معنيين فأكثر لا علاقة بينهما", "اللفظ الخفي المعنى المحتاج إلى بيان"], "العام يستغرق جميع أفراده دفعة واحدة كلفظ المؤمنين. أما الدال على فرد شائع فهو المطلق، وذو المعاني المتعددة هو المشترك، والمحتاج إلى بيان هو المجمل."] },

  { id: "ulc-058", s: "ulum", g: 3, d: 3, t: ["amm-khass", "takhsis"], v: "103:3", w: 1, src: "al-Suyūṭī, al-Itqān fī ʿUlūm al-Qurʾān, ch. on general and specific",
    en: ["The highlighted word specifies the general term 'mankind' in the verse before it. What kind of specifier is it?", ["A connected specifier by exception", "A separate specifier from another verse", "A specifier from the Sunna", "A specifier by consensus"], "An exception joined to the same speech is a connected specifier (mukhaṣṣiṣ muttaṣil), like condition, description and limit. Separate specifiers (munfaṣil) are independent texts such as another verse, a hadith or consensus."],
    de: ["Das hervorgehobene Wort spezifiziert den allgemeinen Begriff „der Mensch“ im vorherigen Vers. Welche Art von Spezifizierer ist es?", ["Ein verbundener Spezifizierer durch Ausnahme", "Ein getrennter Spezifizierer aus einem anderen Vers", "Ein Spezifizierer aus der Sunna", "Ein Spezifizierer durch Konsens"], "Eine Ausnahme in derselben Rede ist ein verbundener Spezifizierer (mukhaṣṣiṣ muttaṣil), ebenso Bedingung, Eigenschaft und Grenze. Getrennte Spezifizierer (munfaṣil) sind eigenständige Texte wie ein anderer Vers, ein Hadith oder der Konsens."],
    ar: ["الكلمة المظللة خصّصت لفظ «الإنسان» العام في الآية قبلها. ما نوع هذا المخصِّص؟", ["مخصِّص متصل بالاستثناء", "مخصِّص منفصل من آية أخرى", "مخصِّص من السنة", "مخصِّص بالإجماع"], "الاستثناء المتصل بالكلام مخصِّص متصل، ومثله الشرط والصفة والغاية. أما المخصِّص المنفصل فنص مستقل كآية أخرى أو حديث أو إجماع."] },

  { id: "ulc-059", s: "ulum", g: 3, d: 4, t: ["amm-khass", "takhsis"], v: "2:228", src: "al-Suyūṭī, al-Itqān fī ʿUlūm al-Qurʾān, ch. on general and specific; Ibn Kathīr, Tafsīr, on 2:228 and 33:49",
    en: ["The verse shown sets three menstrual cycles as the waiting period of divorced women in general. For which group does 33:49 specify it?", ["Women divorced before the marriage was consummated", "Women who are pregnant at the time of divorce", "Women whose husbands have died", "Women who no longer menstruate due to age"], "33:49 states that women divorced before consummation have no waiting period, which specifies the general ruling. Pregnant women and women past menstruation are dealt with in 65:4, and widows in 2:234."],
    de: ["Der gezeigte Vers legt drei Zyklen als Wartezeit geschiedener Frauen allgemein fest. Für welche Gruppe spezifiziert 33:49 dies?", ["Frauen, die vor dem Vollzug der Ehe geschieden wurden", "Frauen, die bei der Scheidung schwanger sind", "Frauen, deren Ehemann verstorben ist", "Frauen, die altersbedingt nicht mehr menstruieren"], "33:49 bestimmt, dass Frauen, die vor dem Vollzug geschieden werden, keine Wartezeit haben, was die allgemeine Regelung spezifiziert. Schwangere und Frauen nach der Menopause behandelt 65:4, Witwen 2:234."],
    ar: ["جعلت الآية المعروضة عدة المطلقات عمومًا ثلاثة قروء. لأيّ فئة خصّصتها الآية 33:49؟", ["المطلقة قبل الدخول", "المطلقة الحامل", "المتوفى عنها زوجها", "الآيسة من المحيض"], "نصّت الآية 33:49 على أن المطلقة قبل المسيس لا عدة عليها، فخصّت عموم المطلقات. أما الحامل والآيسة ففي الآية 65:4، والمتوفى عنها ففي الآية 2:234."] },

  { id: "ulc-060", s: "ulum", g: 4, d: 5, t: ["amm-khass", "takhsis", "usul-differences"], tr: ["hanafi", "jumhur", "comparative"], src: "al-Sarakhsī, Uṣūl al-Sarakhsī, ch. on the general; al-Ghazālī, al-Mustaṣfā, ch. on the general; al-Zurqānī, Manāhil al-ʿIrfān",
    en: ["Which statement correctly describes the difference between the Ḥanafīs and the majority on the indication of an unspecified general word?", ["Ḥanafīs: definitive, so no first specification by an āḥād report; majority: probable", "Ḥanafīs: probable; majority: definitive, so it can never be specified at all", "Both: definitive, so a general Quranic word is never specified by the Sunna", "Both: probable, so a general Quranic word may be specified only by analogy"], "The Ḥanafīs held that a general word not yet specified indicates all its individuals definitively, so a solitary hadith cannot be the first to specify a general Quranic text. The majority held its indication to be probable and allowed specification by a sound solitary hadith."],
    de: ["Welche Aussage beschreibt den Unterschied zwischen den Ḥanafiten und der Mehrheit bei der Aussagekraft eines noch nicht spezifizierten allgemeinen Wortes korrekt?", ["Ḥanafiten: sicher, daher kein erstes takhṣīṣ durch Einzelbericht; Mehrheit: wahrscheinlich", "Ḥanafiten: wahrscheinlich; Mehrheit: sicher, daher gar nicht spezifizierbar", "Beide: sicher, daher nie durch die Sunna spezifizierbar, auch nicht mutawātir", "Beide: wahrscheinlich, daher nur durch Analogie spezifizierbar, nie durch Hadith"], "Die Ḥanafiten hielten fest, dass ein noch nicht spezifiziertes allgemeines Wort alle Einzelfälle sicher bezeichnet; ein Einzelhadith kann daher einen allgemeinen Koranvers nicht als Erstes spezifizieren. Die Mehrheit hielt die Aussage für wahrscheinlich und ließ die Spezifizierung durch einen gesunden Einzelhadith zu."],
    ar: ["ما العبارة الصحيحة في بيان الخلاف بين الحنفية والجمهور في دلالة العام الذي لم يُخصَّص؟", ["الحنفية: قطعية فلا يخصّصه خبر الواحد ابتداءً؛ الجمهور: ظنية", "الحنفية: ظنية؛ الجمهور: قطعية فلا يجوز تخصيصه أصلًا", "الفريقان: قطعية فلا تخصّصها السنة ولو كانت متواترة", "الفريقان: ظنية فلا يخصّصها إلا القياس دون الحديث"], "ذهب الحنفية إلى أن دلالة العام قبل تخصيصه على جميع أفراده قطعية، فلا يخصّص عمومَ القرآن خبرُ الواحد ابتداءً. وذهب الجمهور إلى أنها ظنية فأجازوا تخصيصه بخبر الواحد الصحيح."] },

  { id: "ulc-061", s: "ulum", g: 4, d: 4, t: ["amm-khass"], v: "3:173", w: 4, src: "al-Suyūṭī, al-Itqān fī ʿUlūm al-Qurʾān, ch. on general and specific; al-Ṭabarī, Jāmiʿ al-Bayān, on 3:173",
    en: ["Al-Suyūṭī cites the highlighted word ('the people') in the verse shown as an example of which category?", ["A general word by which something specific is intended", "A general word that remains fully general in meaning", "An unrestricted word that was restricted later on", "A shared word that has several unrelated meanings"], "Many mufassirūn report that the first 'people' here refers to one man (often named as Nuʿaym ibn Masʿūd) or a small group, so the general form intends something specific (ʿāmm urīda bihi al-khuṣūṣ). This differs from a general word later specified by another proof."],
    de: ["Al-Suyūṭī führt das hervorgehobene Wort („die Leute“) im gezeigten Vers als Beispiel für welche Kategorie an?", ["Ein allgemeines Wort, mit dem etwas Bestimmtes gemeint ist", "Ein allgemeines Wort, das in seiner Bedeutung ganz allgemein bleibt", "Ein unbeschränktes Wort, das später eingeschränkt wurde", "Ein mehrdeutiges Wort mit mehreren unverbundenen Bedeutungen"], "Viele Exegeten berichten, dass mit den ersten „Leuten“ hier ein einzelner Mann (oft Nuʿaym ibn Masʿūd) oder eine kleine Gruppe gemeint ist; die allgemeine Form meint also etwas Bestimmtes (ʿāmm urīda bihi al-khuṣūṣ). Das unterscheidet sich von einem allgemeinen Wort, das später durch einen anderen Beleg spezifiziert wird."],
    ar: ["مثّل السيوطي بالكلمة المظللة (الناس) في الآية المعروضة لأيّ قسم؟", ["العام المراد به الخصوص", "العام الباقي على عمومه", "المطلق الذي قُيّد بعد ذلك", "المشترك ذو المعاني المتعددة"], "ذكر كثير من المفسرين أن المراد بالناس الأولى رجل واحد (يُسمّى غالبًا نعيم بن مسعود) أو نفر قليل، فهو لفظ عام أُريد به الخصوص من أول الأمر، بخلاف العام المخصوص الذي يُخرج بعض أفراده دليل آخر."] },

  // ---- muṭlaq and muqayyad ----
  { id: "ulc-062", s: "ulum", g: 2, d: 2, t: ["mutlaq-muqayyad"], src: "al-Suyūṭī, al-Itqān fī ʿUlūm al-Qurʾān, ch. on unrestricted and restricted",
    en: ["What distinguishes a muṭlaq (unrestricted) word from an ʿāmm (general) word?", ["Muṭlaq means any one of a kind; ʿāmm covers all its individuals at once", "Muṭlaq covers all its individuals at once; ʿāmm means any one of a kind", "Muṭlaq appears only in Meccan verses, ʿāmm appears only in Medinan ones", "Muṭlaq rulings are always abrogated, while ʿāmm rulings never are"], "A muṭlaq word, such as 'a slave' in an expiation, is fulfilled by any one individual of the kind; an ʿāmm word, such as 'the believers', includes every individual. Restricting a muṭlaq is taqyīd, limiting an ʿāmm is takhṣīṣ."],
    de: ["Was unterscheidet ein muṭlaq-Wort (unbeschränktes Wort) von einem ʿāmm-Wort (allgemeinen Wort)?", ["Muṭlaq meint irgendein Einzelnes einer Art; ʿāmm umfasst alle zugleich", "Muṭlaq umfasst alle zugleich; ʿāmm meint irgendein Einzelnes einer Art", "Muṭlaq steht nur in mekkanischen, ʿāmm nur in medinensischen Versen", "Muṭlaq-Regelungen sind immer abrogiert, ʿāmm-Regelungen nie"], "Ein muṭlaq-Wort wie „ein Sklave“ bei einer Sühne wird durch irgendein Einzelnes der Art erfüllt; ein ʿāmm-Wort wie „die Gläubigen“ umfasst jedes Einzelne. Die Einschränkung eines muṭlaq ist taqyīd, die Beschränkung eines ʿāmm takhṣīṣ."],
    ar: ["ما الفرق بين المطلق والعام؟", ["المطلق يتناول فردًا شائعًا، والعام يستغرق جميع أفراده", "المطلق يستغرق جميع الأفراد، والعام يتناول فردًا شائعًا", "المطلق لا يرد إلا في المكي، والعام لا يرد إلا في المدني", "المطلق منسوخ دائمًا، والعام لا يدخله النسخ أبدًا"], "المطلق كلفظ «رقبة» في الكفارة يتحقق بأيّ فرد من جنسه، والعام كلفظ «المؤمنين» يشمل كل فرد. وتقييد المطلق تقييد، وقصر العام تخصيص."] },

  { id: "ulc-063", s: "ulum", g: 4, d: 5, t: ["mutlaq-muqayyad", "usul-differences"], v: "4:92", w: 15, tr: ["hanafi", "shafii", "jumhur", "comparative"], src: "al-Suyūṭī, al-Itqān, ch. on unrestricted and restricted; Ibn Qudāma, al-Mughnī, Kitāb al-Ẓihār; al-Sarakhsī, Uṣūl",
    en: ["In the verse shown, the slave freed in expiation for accidental killing is restricted by the highlighted word ('believing'); in the ẓihār expiation (58:3) it is unrestricted. Which describes the positions?", ["Majority (incl. Shāfiʿīs) extend it to ẓihār; Ḥanafīs do not, as causes differ", "Ḥanafīs extend it to ẓihār; the majority do not, as the causes differ", "All schools agree that 58:3 itself requires a believing slave in ẓihār", "All schools agree that 4:92 was abrogated by the unrestricted wording of 58:3"], "Here the ruling (freeing a slave) is the same but the causes (killing, ẓihār) differ. The majority, including the Shāfiʿīs, carry the unrestricted onto the restricted and require a believing slave in ẓihār too; the Ḥanafīs do not, holding that each text keeps its own wording."],
    de: ["Im gezeigten Vers ist der zur Sühne bei versehentlicher Tötung freigelassene Sklave durch das hervorgehobene Wort („gläubig“) eingeschränkt; bei der ẓihār-Sühne (58:3) ist er unbeschränkt. Was beschreibt die Positionen?", ["Mehrheit (inkl. Schāfiʿiten) überträgt es auf ẓihār; Ḥanafiten nicht, da Ursachen verschieden", "Ḥanafiten übertragen es auf ẓihār; die Mehrheit nicht, da die Ursachen verschieden sind", "Alle Schulen: Schon 58:3 selbst verlangt beim ẓihār einen gläubigen Sklaven", "Alle Schulen: 4:92 wurde durch den unbeschränkten Wortlaut von 58:3 abrogiert"], "Hier ist die Regelung (Sklavenbefreiung) dieselbe, die Ursachen (Tötung, ẓihār) sind verschieden. Die Mehrheit, darunter die Schāfiʿiten, bezieht das Unbeschränkte auf das Eingeschränkte und verlangt auch bei ẓihār einen gläubigen Sklaven; die Ḥanafiten nicht, da jeder Text seinen eigenen Wortlaut behalte."],
    ar: ["في الآية المعروضة قُيّدت الرقبة في كفارة القتل الخطأ بالكلمة المظللة (مؤمنة)، وأُطلقت في كفارة الظهار (58:3). ما الوصف الصحيح للأقوال؟", ["الجمهور ومنهم الشافعية يقيّدون الظهار، والحنفية لا لاختلاف السبب", "الحنفية يقيّدون الظهار، والجمهور لا لاختلاف السبب", "اتفقت المذاهب على أن نص 58:3 نفسه يشترط الإيمان في رقبة الظهار", "اتفقت المذاهب على أن الآية 4:92 منسوخة بإطلاق الآية 58:3"], "اتحد الحكم هنا (تحرير رقبة) واختلف السبب (القتل والظهار). فحمل الجمهور ومنهم الشافعية المطلق على المقيد واشترطوا الإيمان في رقبة الظهار، ولم يحمله الحنفية بل أبقوا كل نص على لفظه."] },

  { id: "ulc-064", s: "ulum", g: 3, d: 4, t: ["mutlaq-muqayyad"], v: "6:145", w: 18, src: "al-Suyūṭī, al-Itqān fī ʿUlūm al-Qurʾān, ch. on unrestricted and restricted; al-Qurṭubī, al-Jāmiʿ li-Aḥkām al-Qurʾān, on 6:145",
    en: ["Scholars use the highlighted word ('poured forth') in the verse shown to restrict which unrestricted term?", ["The forbidden blood mentioned in 5:3", "The forbidden carrion mentioned in 5:3", "The wine mentioned in 5:90", "The game of the sea mentioned in 5:96"], "Blood is forbidden without qualification in 5:3 and 2:173 but described as 'poured forth' here. Because the ruling and the cause are the same, scholars carry the unrestricted onto the restricted, so blood remaining in the meat and veins after slaughter is not included."],
    de: ["Welchen unbeschränkten Begriff schränken Gelehrte durch das hervorgehobene Wort („vergossen“) im gezeigten Vers ein?", ["Das verbotene Blut in 5:3", "Das verbotene Verendete in 5:3", "Den Wein in 5:90", "Das Meereswild in 5:96"], "Blut ist in 5:3 und 2:173 ohne Einschränkung verboten, hier aber als „vergossen“ beschrieben. Da Regelung und Ursache gleich sind, beziehen die Gelehrten das Unbeschränkte auf das Eingeschränkte; Blut, das nach dem Schlachten im Fleisch und in den Adern bleibt, ist nicht erfasst."],
    ar: ["يُقيِّد العلماء بالكلمة المظللة (مسفوحًا) في الآية المعروضة أيّ لفظ مطلق؟", ["الدم المحرّم في الآية 5:3", "الميتة المحرّمة في الآية 5:3", "الخمر في الآية 5:90", "صيد البحر في الآية 5:96"], "حُرّم الدم مطلقًا في 5:3 و2:173 وقُيّد هنا بالمسفوح، ولاتحاد الحكم والسبب حُمل المطلق على المقيد، فلا يدخل في التحريم ما يبقى في اللحم والعروق بعد الذكاة."] },

  // ---- iʿjāz ----
  { id: "ulc-065", s: "ulum", g: 1, d: 1, t: ["ijaz"], src: "al-Bāqillānī, Iʿjāz al-Qurʾān; al-Suyūṭī, al-Itqān, ch. on the inimitability of the Quran",
    en: ["What does iʿjāz al-Qurʾān mean?", ["The inability of humans to produce the like of the Quran", "The division of the Quran into thirty equal parts", "The rules for reciting the Quran beautifully and correctly", "The explanation of the Quran by the Sunna of the Prophet"], "Iʿjāz means rendering others incapable: the Quran challenged its audience to produce something like it, and their failure proves that it is from God. The other options describe divisions, tajwīd and tafsīr."],
    de: ["Was bedeutet iʿjāz al-Qurʾān?", ["Die Unfähigkeit der Menschen, dem Koran Gleiches hervorzubringen", "Die Einteilung des Korans in dreißig gleiche Teile", "Die Regeln für die schöne und richtige Rezitation", "Die Erklärung des Korans durch die Sunna des Propheten"], "Iʿjāz bedeutet, andere unfähig zu machen: Der Koran forderte seine Hörer heraus, Gleiches hervorzubringen, und ihr Scheitern beweist, dass er von Gott ist. Die anderen Optionen beschreiben Einteilung, Tajwīd und Tafsīr."],
    ar: ["ما المقصود بإعجاز القرآن؟", ["عجز البشر عن الإتيان بمثل القرآن", "تقسيم القرآن إلى ثلاثين جزءًا متساوية", "أحكام تلاوة القرآن وتحسين أدائه", "تفسير القرآن بسنة النبي صلى الله عليه وسلم"], "الإعجاز إثبات العجز: تحدّى القرآن المخاطَبين أن يأتوا بمثله فعجزوا، فدل ذلك على أنه من عند الله. أما الخيارات الأخرى فتتعلق بالتجزئة والتجويد والتفسير."] },

  { id: "ulc-066", s: "ulum", g: 1, d: 2, t: ["ijaz", "challenge-verses"], v: "17:88", src: "Ibn Kathīr, Tafsīr al-Qurʾān al-ʿAẓīm, on 17:88",
    en: ["What does the verse shown declare about the challenge of the Quran?", ["Humans and jinn together could not produce the like of this Quran", "Only the Arabs of Quraysh were challenged to produce ten surahs", "Anyone could produce one verse like it but not a surah", "The challenge would end with the death of the Prophet"], "The verse states that even if humankind and the jinn gathered and supported one another, they could not bring the like of this Quran. It challenges with the whole Quran and is addressed to all, not only to Quraysh."],
    de: ["Was erklärt der gezeigte Vers über die Herausforderung des Korans?", ["Menschen und Dschinn zusammen könnten nichts Gleiches hervorbringen", "Nur die Araber der Quraysh wurden zu zehn Suren herausgefordert", "Jeder könne einen gleichen Vers hervorbringen, aber keine Sure", "Die Herausforderung ende mit dem Tod des Propheten"], "Der Vers sagt, dass selbst wenn Menschen und Dschinn sich versammelten und einander unterstützten, sie nichts diesem Koran Gleiches hervorbringen könnten. Er fordert mit dem ganzen Koran heraus und richtet sich an alle, nicht nur an die Quraysh."],
    ar: ["ماذا تقرر الآية المعروضة في شأن التحدي بالقرآن؟", ["أن الإنس والجن لو اجتمعوا لا يأتون بمثل هذا القرآن", "أن قريشًا وحدها تُحدّيت بعشر سور", "أن أيّ أحد يستطيع الإتيان بآية مثله لا بسورة", "أن التحدي ينتهي بوفاة النبي صلى الله عليه وسلم"], "تقرر الآية أن الإنس والجن لو اجتمعوا وكان بعضهم لبعض ظهيرًا لا يأتون بمثل هذا القرآن، فهو تحدٍّ بالقرآن كله موجّه إلى الجميع لا إلى قريش وحدها."] },

  { id: "ulc-067", s: "ulum", g: 1, d: 2, t: ["ijaz", "challenge-verses"], v: "11:13", w: 6, src: "Ibn Kathīr, Tafsīr al-Qurʾān al-ʿAẓīm, on 11:13; al-Suyūṭī, al-Itqān, ch. on inimitability",
    en: ["The highlighted word belongs to the phrase stating the size of the challenge in the verse shown. How many surahs are the opponents asked to produce?", ["Ten", "One", "Seven", "Three"], "In this verse those who claim the Quran is fabricated are challenged to bring ten fabricated surahs like it. Elsewhere (10:38, 2:23) the challenge is reduced to a single surah."],
    de: ["Das hervorgehobene Wort gehört zur Wendung, die den Umfang der Herausforderung im gezeigten Vers nennt. Wie viele Suren sollen die Gegner hervorbringen?", ["Zehn", "Eine", "Sieben", "Drei"], "In diesem Vers werden diejenigen, die den Koran für erdichtet halten, herausgefordert, zehn erdichtete Suren gleich ihm zu bringen. An anderer Stelle (10:38, 2:23) wird die Herausforderung auf eine einzige Sure verringert."],
    ar: ["الكلمة المظللة من العبارة التي تحدد مقدار التحدي في الآية المعروضة. بكم سورة طُولب المعارضون؟", ["بعشر سور", "بسورة واحدة", "بسبع سور", "بثلاث سور"], "تحدّت الآية من زعم أن القرآن مفترى أن يأتوا بعشر سور مثله مفتريات، وفي مواضع أخرى (10:38 و2:23) نزل التحدي إلى سورة واحدة."] },

  { id: "ulc-068", s: "ulum", g: 2, d: 3, t: ["ijaz", "challenge-verses"], v: "2:24", w: 4, src: "Ibn Kathīr, Tafsīr al-Qurʾān al-ʿAẓīm, on 2:23–24; al-Zarkashī, al-Burhān, ch. on inimitability",
    en: ["After the challenge in the preceding verse to produce one surah, the highlighted word begins a phrase that adds which element?", ["A firm statement that they will never be able to do it", "A permission to seek the help of poets and orators", "A time limit of one year for meeting the challenge", "A promise of great reward if they should succeed"], "The phrase declares in advance that they will never be able to meet the challenge. Scholars point out that this prediction proved true, which is itself counted among the proofs of the Quran's inimitability."],
    de: ["Nach der Herausforderung im vorigen Vers, eine Sure hervorzubringen, beginnt das hervorgehobene Wort eine Wendung, die welches Element hinzufügt?", ["Eine feste Aussage, dass sie es niemals können werden", "Die Erlaubnis, Dichter und Redner zu Hilfe zu nehmen", "Eine Frist von einem Jahr, um die Herausforderung zu erfüllen", "Ein Versprechen großen Lohns, falls sie Erfolg haben"], "Die Wendung erklärt im Voraus, dass sie die Herausforderung niemals erfüllen werden. Gelehrte weisen darauf hin, dass sich diese Vorhersage bewahrheitet hat, was selbst zu den Belegen der Unnachahmlichkeit gezählt wird."],
    ar: ["بعد التحدي في الآية السابقة بسورة واحدة، تبدأ الكلمة المظللة عبارةً تضيف أيّ معنى؟", ["الجزم بأنهم لن يقدروا على ذلك أبدًا", "الإذن لهم بالاستعانة بالشعراء والخطباء", "تحديد مدة سنة كاملة للتحدي", "الوعد بجزاء عظيم إن نجحوا"], "تقطع العبارة سلفًا بأنهم لن يفعلوا، وقد صدق هذا الخبر فلم يعارضه أحد، فعُدّ ذلك من دلائل الإعجاز أيضًا."] },

  { id: "ulc-069", s: "ulum", g: 4, d: 4, t: ["ijaz", "sarfa"], src: "al-Bāqillānī, Iʿjāz al-Qurʾān; al-Suyūṭī, al-Itqān, ch. on inimitability; al-Zarkashī, al-Burhān",
    en: ["The doctrine of ṣarfa, that God turned the Arabs away from opposing the Quran although they were able to, is associated with whom, and how did the majority respond?", ["al-Naẓẓām; most rejected it, as the miracle would then be the prevention", "al-Bāqillānī; most accepted it as the strongest aspect of iʿjāz", "ʿAbd al-Qāhir al-Jurjānī; most accepted it with some conditions", "al-Zamakhsharī; most considered it the view of the early Salaf"], "Ṣarfa is linked above all to the Muʿtazilī al-Naẓẓām. Al-Bāqillānī, al-Jurjānī and most scholars rejected it, arguing that the Quran itself is inimitable in its composition and that ṣarfa would make the miracle the prevention rather than the text."],
    de: ["Die Lehre der ṣarfa, Gott habe die Araber davon abgehalten, dem Koran etwas entgegenzusetzen, obwohl sie es gekonnt hätten, wird wem zugeschrieben, und wie reagierte die Mehrheit?", ["al-Naẓẓām; die meisten lehnten sie ab, da sonst das Abhalten das Wunder wäre", "al-Bāqillānī; die meisten nahmen sie als stärksten Aspekt des iʿjāz an", "ʿAbd al-Qāhir al-Jurjānī; die meisten nahmen sie mit Bedingungen an", "al-Zamakhsharī; die meisten hielten sie für die Ansicht der frühen Salaf"], "Die ṣarfa wird vor allem mit dem Muʿtaziliten al-Naẓẓām verbunden. Al-Bāqillānī, al-Jurjānī und die meisten Gelehrten lehnten sie ab: Der Koran selbst sei in seiner Fügung unnachahmlich, und die ṣarfa mache das Abhalten statt des Textes zum Wunder."],
    ar: ["القول بالصَّرفة، أي أن الله صرف العرب عن معارضة القرآن مع قدرتهم عليها، يُنسب إلى مَن؟ وما موقف الجمهور منه؟", ["إلى النظّام، وردّه الجمهور لأن المعجز حينئذ هو الصرف", "إلى الباقلاني، وقبله الجمهور بوصفه أقوى وجوه الإعجاز", "إلى عبد القاهر الجرجاني، وقبله الجمهور بشروط", "إلى الزمخشري، وعدّه الجمهور قول السلف المتقدمين"], "اشتهر القول بالصرفة عن النظّام من المعتزلة، وردّه الباقلاني والجرجاني وجمهور العلماء بأن القرآن معجز بنظمه في ذاته، وأن القول بالصرفة يجعل المعجز هو المنع لا القرآن."] },

  { id: "ulc-070", s: "ulum", g: 3, d: 4, t: ["ijaz", "works-on-ijaz"], src: "ʿAbd al-Qāhir al-Jurjānī, Dalāʾil al-Iʿjāz",
    en: ["Which scholar developed the theory of naẓm (the arrangement of meanings through syntax) as the basis of the Quran's inimitability in Dalāʾil al-Iʿjāz?", ["ʿAbd al-Qāhir al-Jurjānī", "Abū Bakr al-Bāqillānī", "Abū Sulaymān al-Khaṭṭābī", "ʿAlī ibn ʿĪsā al-Rummānī"], "Al-Jurjānī argued in Dalāʾil al-Iʿjāz that eloquence lies in naẓm, the way words are arranged according to the meanings of grammar. Al-Bāqillānī (Iʿjāz al-Qurʾān), al-Khaṭṭābī (Bayān Iʿjāz al-Qurʾān) and al-Rummānī (al-Nukat fī Iʿjāz al-Qurʾān) wrote other classical treatises on iʿjāz."],
    de: ["Welcher Gelehrte entwickelte in Dalāʾil al-Iʿjāz die Theorie des naẓm (der Anordnung von Bedeutungen durch die Syntax) als Grundlage der Unnachahmlichkeit des Korans?", ["ʿAbd al-Qāhir al-Jurjānī", "Abū Bakr al-Bāqillānī", "Abū Sulaymān al-Khaṭṭābī", "ʿAlī ibn ʿĪsā al-Rummānī"], "Al-Jurjānī legte in Dalāʾil al-Iʿjāz dar, dass Beredsamkeit im naẓm liegt, der Anordnung der Wörter nach den Bedeutungen der Grammatik. Al-Bāqillānī (Iʿjāz al-Qurʾān), al-Khaṭṭābī (Bayān Iʿjāz al-Qurʾān) und al-Rummānī (al-Nukat fī Iʿjāz al-Qurʾān) verfassten andere klassische Abhandlungen über den iʿjāz."],
    ar: ["مَن العالم الذي أسّس نظرية النظم (توخّي معاني النحو) أساسًا لإعجاز القرآن في كتاب دلائل الإعجاز؟", ["عبد القاهر الجرجاني", "أبو بكر الباقلاني", "أبو سليمان الخطابي", "علي بن عيسى الرماني"], "قرّر الجرجاني في دلائل الإعجاز أن البلاغة في النظم، وهو توخّي معاني النحو فيما بين الكلم. وللباقلاني إعجاز القرآن، وللخطابي بيان إعجاز القرآن، وللرماني النكت في إعجاز القرآن."] },

  { id: "ulc-071", s: "ulum", g: 2, d: 3, t: ["ijaz", "aspects-of-ijaz"], v: "30:2", src: "al-Suyūṭī, al-Itqān, ch. on inimitability; Ibn Kathīr, Tafsīr, on 30:2–4",
    en: ["The verse shown and the two after it, foretelling that the defeated Romans would soon be victorious, are often cited for which aspect of iʿjāz?", ["Informing about the unseen that later came to pass", "The legislative perfection of its rulings", "The miraculous effect of its sound on listeners", "The precise counting of its letters"], "The Romans' defeat and their later victory within a few years, as foretold, is a standard example of the Quran's reports about the unseen. Scholars list this among the aspects of iʿjāz alongside its eloquence and its rulings."],
    de: ["Der gezeigte Vers und die beiden folgenden, die vorhersagen, dass die besiegten Römer bald siegen würden, werden oft für welchen Aspekt des iʿjāz angeführt?", ["Mitteilung über Verborgenes, das später eintraf", "Die gesetzgeberische Vollkommenheit seiner Regelungen", "Die wunderbare Wirkung seines Klangs auf die Hörer", "Die genaue Zählung seiner Buchstaben"], "Die Niederlage der Römer und ihr späterer Sieg innerhalb weniger Jahre, wie vorhergesagt, ist ein Standardbeispiel für die Mitteilungen des Korans über das Verborgene. Gelehrte zählen dies neben Beredsamkeit und Regelungen zu den Aspekten des iʿjāz."],
    ar: ["الآية المعروضة والآيتان بعدها في الإخبار بأن الروم بعد هزيمتهم سيغلبون، يُستشهد بها كثيرًا لأيّ وجه من وجوه الإعجاز؟", ["الإخبار بالغيب الذي وقع كما أخبر", "كمال التشريع في أحكامه", "تأثير صوته في نفوس السامعين", "دقة إحصاء حروفه"], "هُزمت الروم ثم غلبت في بضع سنين كما أخبر القرآن، فصار ذلك مثالًا مشهورًا على الإخبار بالغيوب، وهو من وجوه الإعجاز التي ذكرها العلماء مع البلاغة والتشريع."] },

  // ---- major works of ʿulūm al-Qurʾān ----
  { id: "ulc-072", s: "ulum", g: 1, d: 2, t: ["ulum-works"], src: "al-Suyūṭī, al-Itqān fī ʿUlūm al-Qurʾān, introduction",
    en: ["Who wrote al-Itqān fī ʿUlūm al-Qurʾān?", ["Jalāl al-Dīn al-Suyūṭī", "Badr al-Dīn al-Zarkashī", "Ibn Kathīr", "Ibn al-Jawzī"], "Al-Itqān is by Jalāl al-Dīn al-Suyūṭī and is among the most comprehensive classical works on the Quranic sciences. Al-Zarkashī wrote the earlier al-Burhān, which al-Suyūṭī drew on."],
    de: ["Wer verfasste al-Itqān fī ʿUlūm al-Qurʾān?", ["Jalāl al-Dīn al-Suyūṭī", "Badr al-Dīn al-Zarkashī", "Ibn Kathīr", "Ibn al-Jawzī"], "Al-Itqān stammt von Jalāl al-Dīn al-Suyūṭī und gehört zu den umfassendsten klassischen Werken über die Koranwissenschaften. Al-Zarkashī schrieb das frühere al-Burhān, auf das al-Suyūṭī zurückgriff."],
    ar: ["مَن مؤلف كتاب الإتقان في علوم القرآن؟", ["جلال الدين السيوطي", "بدر الدين الزركشي", "ابن كثير", "ابن الجوزي"], "الإتقان لجلال الدين السيوطي، وهو من أجمع الكتب في علوم القرآن، وقد أفاد فيه من البرهان للزركشي الذي سبقه."] },

  { id: "ulc-073", s: "ulum", g: 2, d: 2, t: ["ulum-works"], src: "al-Zarkashī, al-Burhān fī ʿUlūm al-Qurʾān, introduction",
    en: ["Who is the author of al-Burhān fī ʿUlūm al-Qurʾān?", ["Badr al-Dīn al-Zarkashī", "Jalāl al-Dīn al-Suyūṭī", "Ibn Taymiyya", "Fakhr al-Dīn al-Rāzī"], "Al-Burhān is by the Shāfiʿī scholar Badr al-Dīn al-Zarkashī (8th century AH). Al-Suyūṭī later built on it in al-Itqān."],
    de: ["Wer ist der Verfasser von al-Burhān fī ʿUlūm al-Qurʾān?", ["Badr al-Dīn al-Zarkashī", "Jalāl al-Dīn al-Suyūṭī", "Ibn Taymiyya", "Fakhr al-Dīn al-Rāzī"], "Al-Burhān stammt von dem schāfiʿitischen Gelehrten Badr al-Dīn al-Zarkashī (8. Jahrhundert n. H.). Al-Suyūṭī baute später in al-Itqān darauf auf."],
    ar: ["مَن مؤلف كتاب البرهان في علوم القرآن؟", ["بدر الدين الزركشي", "جلال الدين السيوطي", "ابن تيمية", "فخر الدين الرازي"], "البرهان للعالم الشافعي بدر الدين الزركشي من علماء القرن الثامن الهجري، وبنى عليه السيوطي بعد ذلك في الإتقان."] },

  { id: "ulc-074", s: "ulum", g: 2, d: 3, t: ["ulum-works"], src: "al-Zurqānī, Manāhil al-ʿIrfān fī ʿUlūm al-Qurʾān",
    en: ["Manāhil al-ʿIrfān fī ʿUlūm al-Qurʾān, a widely taught modern work, was written by whom?", ["Muḥammad ʿAbd al-ʿAẓīm al-Zurqānī", "Mannāʿ al-Qaṭṭān", "Ṣubḥī al-Ṣāliḥ", "Muḥammad al-Ṭāhir ibn ʿĀshūr"], "Al-Zurqānī, a scholar of al-Azhar, wrote Manāhil al-ʿIrfān from his lectures. Mannāʿ al-Qaṭṭān and Ṣubḥī al-Ṣāliḥ each wrote a work called Mabāḥith fī ʿUlūm al-Qurʾān; Ibn ʿĀshūr wrote the tafsīr al-Taḥrīr wa-l-Tanwīr."],
    de: ["Wer verfasste Manāhil al-ʿIrfān fī ʿUlūm al-Qurʾān, ein viel gelehrtes modernes Werk?", ["Muḥammad ʿAbd al-ʿAẓīm al-Zurqānī", "Mannāʿ al-Qaṭṭān", "Ṣubḥī al-Ṣāliḥ", "Muḥammad al-Ṭāhir ibn ʿĀshūr"], "Al-Zurqānī, ein Gelehrter der Azhar, verfasste Manāhil al-ʿIrfān aus seinen Vorlesungen. Mannāʿ al-Qaṭṭān und Ṣubḥī al-Ṣāliḥ schrieben jeweils ein Werk namens Mabāḥith fī ʿUlūm al-Qurʾān; Ibn ʿĀshūr verfasste den Tafsīr al-Taḥrīr wa-l-Tanwīr."],
    ar: ["مَن مؤلف كتاب مناهل العرفان في علوم القرآن، وهو من الكتب الحديثة المعتمدة في التدريس؟", ["محمد عبد العظيم الزرقاني", "منّاع القطان", "صبحي الصالح", "محمد الطاهر بن عاشور"], "ألّف الزرقاني من علماء الأزهر مناهل العرفان من محاضراته. ولكلٍّ من منّاع القطان وصبحي الصالح كتاب «مباحث في علوم القرآن»، ولابن عاشور تفسير التحرير والتنوير."] },

  { id: "ulc-075", s: "ulum", g: 3, d: 4, t: ["ulum-works"], src: "al-Zarkashī, al-Burhān, introduction; al-Suyūṭī, al-Itqān, introduction",
    en: ["How are al-Burhān of al-Zarkashī and al-Itqān of al-Suyūṭī divided?", ["al-Burhān into 47 types (anwāʿ), al-Itqān into 80", "al-Burhān into 80 types, al-Itqān into 47", "Both into 114 chapters following the surahs", "Both into 30 parts following the ajzāʾ"], "Al-Zarkashī arranged al-Burhān in forty-seven types of knowledge; al-Suyūṭī, building on it and on his own earlier al-Taḥbīr, arranged al-Itqān in eighty types."],
    de: ["Wie sind al-Burhān von al-Zarkashī und al-Itqān von al-Suyūṭī gegliedert?", ["al-Burhān in 47 Arten (anwāʿ), al-Itqān in 80", "al-Burhān in 80 Arten, al-Itqān in 47", "Beide in 114 Kapitel nach den Suren", "Beide in 30 Teile nach den ajzāʾ"], "Al-Zarkashī ordnete al-Burhān in siebenundvierzig Wissensarten; al-Suyūṭī, der darauf und auf seinem früheren al-Taḥbīr aufbaute, gliederte al-Itqān in achtzig Arten."],
    ar: ["كيف قُسّم كتاب البرهان للزركشي وكتاب الإتقان للسيوطي؟", ["البرهان في سبعة وأربعين نوعًا، والإتقان في ثمانين نوعًا", "البرهان في ثمانين نوعًا، والإتقان في سبعة وأربعين", "كلاهما في مئة وأربعة عشر بابًا على عدد السور", "كلاهما في ثلاثين قسمًا على عدد الأجزاء"], "رتّب الزركشي البرهان على سبعة وأربعين نوعًا، ورتّب السيوطي الإتقان على ثمانين نوعًا مستفيدًا من البرهان ومن كتابه السابق التحبير."] },

  { id: "ulc-076", s: "ulum", g: 4, d: 5, t: ["ulum-works", "tafsir-works"], src: "al-Suyūṭī, al-Itqān fī ʿUlūm al-Qurʾān, introduction",
    en: ["Al-Suyūṭī wrote al-Itqān as an introduction to a larger tafsīr he planned. What was that tafsīr called?", ["Majmaʿ al-Baḥrayn wa-Maṭlaʿ al-Badrayn", "al-Durr al-Manthūr fī al-Tafsīr bi-l-Maʾthūr", "Tafsīr al-Jalālayn", "Lubāb al-Nuqūl fī Asbāb al-Nuzūl"], "In his introduction al-Suyūṭī says he made al-Itqān a preface to his great tafsīr Majmaʿ al-Baḥrayn wa-Maṭlaʿ al-Badrayn. Al-Durr al-Manthūr is his collection of transmitted reports, al-Jalālayn a concise tafsīr he completed after al-Maḥallī, and Lubāb al-Nuqūl a book on occasions of revelation."],
    de: ["Al-Suyūṭī schrieb al-Itqān als Einleitung zu einem größeren geplanten Tafsīr. Wie hieß dieser Tafsīr?", ["Majmaʿ al-Baḥrayn wa-Maṭlaʿ al-Badrayn", "al-Durr al-Manthūr fī al-Tafsīr bi-l-Maʾthūr", "Tafsīr al-Jalālayn", "Lubāb al-Nuqūl fī Asbāb al-Nuzūl"], "In seiner Einleitung sagt al-Suyūṭī, er habe al-Itqān als Vorrede zu seinem großen Tafsīr Majmaʿ al-Baḥrayn wa-Maṭlaʿ al-Badrayn verfasst. Al-Durr al-Manthūr ist seine Sammlung überlieferter Berichte, al-Jalālayn ein knapper Tafsīr, den er nach al-Maḥallī vollendete, und Lubāb al-Nuqūl ein Buch über Offenbarungsanlässe."],
    ar: ["جعل السيوطي الإتقان مقدمةً لتفسير كبير عزم عليه. ما اسم ذلك التفسير؟", ["مجمع البحرين ومطلع البدرين", "الدر المنثور في التفسير بالمأثور", "تفسير الجلالين", "لباب النقول في أسباب النزول"], "ذكر السيوطي في مقدمة الإتقان أنه جعله مقدمة لتفسيره الكبير مجمع البحرين ومطلع البدرين. أما الدر المنثور فجمع فيه المأثور، والجلالين أتمّه بعد المحلي، ولباب النقول في أسباب النزول."] },

  // ---- history of tafsīr ----
  { id: "ulc-077", s: "ulum", g: 1, d: 1, t: ["tafsir-history", "companion-mufassirun"], src: "al-Suyūṭī, al-Itqān, ch. on the classes of mufassirūn; Ibn Kathīr, Tafsīr, introduction",
    en: ["Which Companion is known by the title Turjumān al-Qurʾān (interpreter of the Quran)?", ["ʿAbd Allāh ibn ʿAbbās", "ʿAbd Allāh ibn ʿUmar", "Abū Hurayra", "Anas ibn Mālik"], "Ibn ʿAbbās was given this title by Ibn Masʿūd and is known for the Prophet's supplication for him to be given understanding in religion. His students formed the Meccan school of tafsīr."],
    de: ["Welcher Gefährte ist unter dem Titel Turjumān al-Qurʾān (Dolmetscher des Korans) bekannt?", ["ʿAbd Allāh ibn ʿAbbās", "ʿAbd Allāh ibn ʿUmar", "Abū Hurayra", "Anas ibn Mālik"], "Ibn ʿAbbās erhielt diesen Titel von Ibn Masʿūd und ist für das Bittgebet des Propheten bekannt, ihm Verständnis in der Religion zu geben. Seine Schüler bildeten die mekkanische Tafsīr-Schule."],
    ar: ["أيّ الصحابة يُلقَّب بترجمان القرآن؟", ["عبد الله بن عباس", "عبد الله بن عمر", "أبو هريرة", "أنس بن مالك"], "لقّبه بذلك ابن مسعود، وهو معروف بدعاء النبي صلى الله عليه وسلم له بالفقه في الدين، وعن تلاميذه نشأت مدرسة التفسير المكية."] },

  { id: "ulc-078", s: "ulum", g: 1, d: 2, t: ["tafsir-history", "tafsir-methods"], src: "Ibn Taymiyya, Muqaddima fī Uṣūl al-Tafsīr; al-Zurqānī, Manāhil al-ʿIrfān, ch. on tafsīr",
    en: ["What is meant by al-tafsīr bi-l-maʾthūr?", ["Tafsīr by transmitted reports: Quran, Sunna and the Companions", "Tafsīr based mainly on the rules of grammar and rhetoric", "Tafsīr based on the personal reasoning of the mufassir alone", "Tafsīr based on hidden symbolic meanings of the letters"], "Al-tafsīr bi-l-maʾthūr explains the Quran by the Quran, by the Sunna, and by what is reported from the Companions (and, for many, the Tābiʿūn). Tafsīr bi-l-raʾy relies on reasoned ijtihād, which is praiseworthy only when grounded in knowledge."],
    de: ["Was ist mit al-tafsīr bi-l-maʾthūr gemeint?", ["Tafsīr durch Überliefertes: Koran, Sunna und die Gefährten", "Tafsīr vor allem nach den Regeln von Grammatik und Rhetorik", "Tafsīr allein nach der persönlichen Überlegung des Exegeten", "Tafsīr nach verborgenen symbolischen Bedeutungen der Buchstaben"], "Al-tafsīr bi-l-maʾthūr erklärt den Koran durch den Koran, die Sunna und das von den Gefährten (und für viele den Tābiʿūn) Überlieferte. Tafsīr bi-l-raʾy stützt sich auf begründeten ijtihād und ist nur lobenswert, wenn er auf Wissen beruht."],
    ar: ["ما المقصود بالتفسير بالمأثور؟", ["التفسير بالمنقول: القرآن والسنة وأقوال الصحابة", "التفسير المعتمد أساسًا على النحو والبلاغة", "التفسير المعتمد على رأي المفسر وحده", "التفسير بالمعاني الرمزية الخفية للحروف"], "التفسير بالمأثور تفسير القرآن بالقرآن وبالسنة وبما نُقل عن الصحابة، ويُلحق به عند كثيرين ما نُقل عن التابعين. أما التفسير بالرأي فقائم على الاجتهاد، ولا يُحمد إلا إذا قام على علم."] },

  { id: "ulc-079", s: "ulum", g: 1, d: 2, t: ["tafsir-history", "tafsir-works"], src: "al-Ṭabarī, Jāmiʿ al-Bayān ʿan Taʾwīl Āy al-Qurʾān, introduction",
    en: ["Who wrote Jāmiʿ al-Bayān ʿan Taʾwīl Āy al-Qurʾān, the great early tafsīr built on transmitted reports?", ["Ibn Jarīr al-Ṭabarī", "ʿImād al-Dīn Ibn Kathīr", "Abū ʿAbd Allāh al-Qurṭubī", "al-Ḥusayn ibn Masʿūd al-Baghawī"], "Al-Ṭabarī (d. 310 AH) collected the reports of the Companions and Tābiʿūn with their chains and weighed between them, which made his tafsīr a primary reference for later mufassirūn."],
    de: ["Wer verfasste Jāmiʿ al-Bayān ʿan Taʾwīl Āy al-Qurʾān, den großen frühen Tafsīr auf Grundlage überlieferter Berichte?", ["Ibn Jarīr al-Ṭabarī", "ʿImād al-Dīn Ibn Kathīr", "Abū ʿAbd Allāh al-Qurṭubī", "al-Ḥusayn ibn Masʿūd al-Baghawī"], "Al-Ṭabarī (gest. 310 n. H.) sammelte die Berichte der Gefährten und Tābiʿūn mit ihren Überlieferungsketten und wog zwischen ihnen ab; dadurch wurde sein Tafsīr zur Hauptquelle späterer Exegeten."],
    ar: ["مَن مؤلف جامع البيان عن تأويل آي القرآن، التفسير الكبير المتقدم القائم على المأثور؟", ["ابن جرير الطبري", "عماد الدين ابن كثير", "أبو عبد الله القرطبي", "الحسين بن مسعود البغوي"], "جمع الطبري (ت 310 هـ) أقوال الصحابة والتابعين بأسانيدها ورجّح بينها، فصار تفسيره مرجعًا أساسيًّا للمفسرين بعده."] },

  { id: "ulc-080", s: "ulum", g: 1, d: 1, t: ["tafsir-history", "tafsir-works"], src: "Ibn Kathīr, Tafsīr al-Qurʾān al-ʿAẓīm, introduction",
    en: ["Tafsīr al-Qurʾān al-ʿAẓīm, one of the most widely read tafsīrs, was written by whom?", ["Ibn Kathīr", "al-Ṭabarī", "al-Zamakhsharī", "al-Bayḍāwī"], "Ibn Kathīr, a student of Ibn Taymiyya, explains the Quran by the Quran, the Sunna and the reports of the Salaf, and often comments on the reliability of the reports he cites."],
    de: ["Wer verfasste Tafsīr al-Qurʾān al-ʿAẓīm, einen der meistgelesenen Tafsīre?", ["Ibn Kathīr", "al-Ṭabarī", "al-Zamakhsharī", "al-Bayḍāwī"], "Ibn Kathīr, ein Schüler Ibn Taymiyyas, erklärt den Koran durch den Koran, die Sunna und die Berichte der Salaf und äußert sich oft zur Verlässlichkeit der angeführten Berichte."],
    ar: ["مَن مؤلف تفسير القرآن العظيم، وهو من أكثر التفاسير تداولًا؟", ["ابن كثير", "الطبري", "الزمخشري", "البيضاوي"], "ابن كثير تلميذ ابن تيمية، فسّر القرآن بالقرآن وبالسنة وبآثار السلف، وكثيرًا ما يبيّن درجة ما يورده من الروايات."] },

  { id: "ulc-081", s: "ulum", g: 2, d: 2, t: ["tafsir-history", "tafsir-works"], src: "al-Suyūṭī, Tafsīr al-Jalālayn, conclusion",
    en: ["Which two scholars wrote Tafsīr al-Jalālayn?", ["Jalāl al-Dīn al-Maḥallī and Jalāl al-Dīn al-Suyūṭī", "Jalāl al-Dīn al-Suyūṭī and Badr al-Dīn al-Zarkashī", "Jalāl al-Dīn al-Maḥallī and Ibn Ḥajar al-ʿAsqalānī", "Jalāl al-Dīn al-Rūmī and Jalāl al-Dīn al-Suyūṭī"], "The name means 'the two Jalāls'. Al-Maḥallī explained from al-Kahf to the end and al-Fātiḥa, then died; al-Suyūṭī completed the first half from al-Baqara to al-Isrāʾ in the same concise style."],
    de: ["Welche beiden Gelehrten verfassten Tafsīr al-Jalālayn?", ["Jalāl al-Dīn al-Maḥallī und Jalāl al-Dīn al-Suyūṭī", "Jalāl al-Dīn al-Suyūṭī und Badr al-Dīn al-Zarkashī", "Jalāl al-Dīn al-Maḥallī und Ibn Ḥajar al-ʿAsqalānī", "Jalāl al-Dīn al-Rūmī und Jalāl al-Dīn al-Suyūṭī"], "Der Name bedeutet „die beiden Jalāl“. Al-Maḥallī erklärte von al-Kahf bis zum Ende sowie al-Fātiḥa und starb dann; al-Suyūṭī vollendete die erste Hälfte von al-Baqara bis al-Isrāʾ im selben knappen Stil."],
    ar: ["مَن العالمان اللذان ألّفا تفسير الجلالين؟", ["جلال الدين المحلي وجلال الدين السيوطي", "جلال الدين السيوطي وبدر الدين الزركشي", "جلال الدين المحلي وابن حجر العسقلاني", "جلال الدين الرومي وجلال الدين السيوطي"], "سُمّي بالجلالين نسبةً إلى الجلالين. فسّر المحلي من سورة الكهف إلى آخر القرآن ثم الفاتحة وتوفي، فأتمّه السيوطي من البقرة إلى آخر الإسراء على طريقته في الإيجاز."] },

  { id: "ulc-082", s: "ulum", g: 2, d: 3, t: ["tafsir-history", "tafsir-methods"], src: "Ibn Taymiyya, Muqaddima fī Uṣūl al-Tafsīr; Ibn Kathīr, Tafsīr, introduction",
    en: ["According to Ibn Taymiyya in his Muqaddima fī Uṣūl al-Tafsīr, what is the soundest first step in explaining a verse?", ["Explaining the Quran by the Quran", "Explaining it by the Arabic poetry of the Jāhiliyya", "Explaining it by the reports of the People of the Book", "Explaining it by the mufassir's own reasoning"], "Ibn Taymiyya lists the best methods in order: the Quran by the Quran, then by the Sunna, then by the sayings of the Companions, then of the Tābiʿūn. Ibn Kathīr adopts this order in the introduction to his tafsīr."],
    de: ["Was ist nach Ibn Taymiyya in seiner Muqaddima fī Uṣūl al-Tafsīr der richtigste erste Schritt bei der Erklärung eines Verses?", ["Die Erklärung des Korans durch den Koran", "Die Erklärung durch die arabische Dichtung der Jāhiliyya", "Die Erklärung durch Berichte der Leute der Schrift", "Die Erklärung durch die eigene Überlegung des Exegeten"], "Ibn Taymiyya nennt die besten Methoden in dieser Reihenfolge: Koran durch Koran, dann durch die Sunna, dann durch Aussagen der Gefährten, dann der Tābiʿūn. Ibn Kathīr übernimmt diese Reihenfolge in der Einleitung seines Tafsīr."],
    ar: ["ما أصح طرق التفسير وأولها عند ابن تيمية في مقدمته في أصول التفسير؟", ["تفسير القرآن بالقرآن", "تفسيره بشعر العرب في الجاهلية", "تفسيره بأخبار أهل الكتاب", "تفسيره برأي المفسر"], "رتّب ابن تيمية أحسن طرق التفسير: القرآن بالقرآن، ثم بالسنة، ثم بأقوال الصحابة، ثم بأقوال التابعين، وتبعه ابن كثير في مقدمة تفسيره."] },

  { id: "ulc-083", s: "ulum", g: 2, d: 3, t: ["tafsir-history", "tafsir-methods"], src: "al-Zurqānī, Manāhil al-ʿIrfān, ch. on tafsīr bi-l-raʾy; al-Suyūṭī, al-Itqān, ch. on the conditions of the mufassir",
    en: ["How do scholars classify tafsīr bi-l-raʾy (tafsīr by reasoning)?", ["Praiseworthy when grounded in the required knowledge, blameworthy when not", "Always forbidden, whatever the qualifications of the mufassir may be", "Always permitted, since every reader may interpret the text freely", "Permitted only for verses about stories, never for verses on rulings"], "Reasoned tafsīr that meets the conditions (knowledge of Arabic, uṣūl, the transmitted tafsīr and the Sunna) and does not contradict them is accepted. Speaking about the Quran without knowledge or to support a preconceived opinion is condemned."],
    de: ["Wie ordnen die Gelehrten den tafsīr bi-l-raʾy (Tafsīr durch Überlegung) ein?", ["Lobenswert, wenn er auf dem nötigen Wissen beruht, tadelnswert, wenn nicht", "Immer verboten, gleich welche Qualifikation der Exeget besitzt", "Immer erlaubt, da jeder Leser den Text frei deuten darf", "Nur für Erzählverse erlaubt, niemals für Verse über Regelungen"], "Ein begründeter Tafsīr, der die Bedingungen erfüllt (Kenntnis des Arabischen, der uṣūl, des überlieferten Tafsīr und der Sunna) und ihnen nicht widerspricht, wird angenommen. Über den Koran ohne Wissen oder zur Stützung einer vorgefassten Meinung zu reden, wird verurteilt."],
    ar: ["كيف يقسّم العلماء التفسير بالرأي؟", ["محمود إذا قام على العلوم اللازمة، ومذموم إذا خلا منها", "محرّم دائمًا مهما كانت أهلية المفسر وعلمه", "جائز دائمًا لأن لكل قارئ أن يفسّر كما يشاء", "جائز في آيات القصص فقط دون آيات الأحكام"], "التفسير بالرأي المستوفي لشروطه من معرفة العربية والأصول والمأثور والسنة وعدم مخالفتها مقبول، أما القول في القرآن بغير علم أو لنصرة رأي سابق فمذموم."] },

  { id: "ulc-084", s: "ulum", g: 3, d: 3, t: ["tafsir-history", "tabiun-schools"], src: "Ibn Taymiyya, Muqaddima fī Uṣūl al-Tafsīr; al-Suyūṭī, al-Itqān, ch. on the classes of mufassirūn",
    en: ["Which of these Tābiʿūn belongs to the Meccan school of tafsīr, made up of the students of Ibn ʿAbbās?", ["Mujāhid ibn Jabr", "ʿAlqama ibn Qays", "Masrūq ibn al-Ajdaʿ", "Zayd ibn Aslam"], "Ibn Taymiyya names Mujāhid, ʿIkrima, Saʿīd ibn Jubayr, Ṭāwūs and ʿAṭāʾ among the companions of Ibn ʿAbbās in Mecca. ʿAlqama and Masrūq belong to the Kufan school of Ibn Masʿūd, and Zayd ibn Aslam to the Medinan school."],
    de: ["Welcher dieser Tābiʿūn gehört zur mekkanischen Tafsīr-Schule der Schüler Ibn ʿAbbās?", ["Mujāhid ibn Jabr", "ʿAlqama ibn Qays", "Masrūq ibn al-Ajdaʿ", "Zayd ibn Aslam"], "Ibn Taymiyya nennt Mujāhid, ʿIkrima, Saʿīd ibn Jubayr, Ṭāwūs und ʿAṭāʾ unter den Gefährten Ibn ʿAbbās in Mekka. ʿAlqama und Masrūq gehören zur kufischen Schule Ibn Masʿūds, Zayd ibn Aslam zur medinensischen Schule."],
    ar: ["أيّ هؤلاء التابعين من مدرسة التفسير المكية من أصحاب ابن عباس؟", ["مجاهد بن جبر", "علقمة بن قيس", "مسروق بن الأجدع", "زيد بن أسلم"], "ذكر ابن تيمية من أصحاب ابن عباس بمكة مجاهدًا وعكرمة وسعيد بن جبير وطاوسًا وعطاء. أما علقمة ومسروق فمن مدرسة ابن مسعود بالكوفة، وزيد بن أسلم من مدرسة المدينة."] },

  { id: "ulc-085", s: "ulum", g: 3, d: 4, t: ["tafsir-history", "israiliyyat"], src: "Ibn Taymiyya, Muqaddima fī Uṣūl al-Tafsīr; Ibn Kathīr, Tafsīr, introduction",
    en: ["According to Ibn Taymiyya, how should reports from the People of the Book (isrāʾīliyyāt) be treated when nothing in our sources confirms or contradicts them?", ["Neither affirmed nor denied, though they may be narrated", "Accepted as true like the reports of the Companions", "Rejected outright and never narrated", "Accepted only if they concern rulings"], "Ibn Taymiyya, followed by Ibn Kathīr, divides them into three: what our sources confirm is accepted, what they contradict is rejected, and what they neither confirm nor deny is neither believed nor rejected, though it may be narrated; it rarely brings any religious benefit."],
    de: ["Wie sind nach Ibn Taymiyya Berichte der Leute der Schrift (isrāʾīliyyāt) zu behandeln, wenn unsere Quellen sie weder bestätigen noch widerlegen?", ["Weder bestätigt noch verneint, doch sie dürfen erzählt werden", "Als wahr angenommen wie die Berichte der Gefährten", "Völlig abgelehnt und unter keinen Umständen erzählt", "Nur angenommen, wenn sie gesetzliche Regelungen betreffen"], "Ibn Taymiyya, dem Ibn Kathīr folgt, teilt sie in drei: Was unsere Quellen bestätigen, wird angenommen; was sie widerlegen, wird abgelehnt; was sie weder bestätigen noch verneinen, wird weder geglaubt noch verworfen, darf aber erzählt werden, bringt jedoch selten religiösen Nutzen."],
    ar: ["كيف تُعامَل الإسرائيليات عند ابن تيمية إذا لم يرد في شرعنا ما يصدّقها أو يكذّبها؟", ["لا تُصدَّق ولا تُكذَّب، وتجوز حكايتها", "تُقبل وتُصدَّق كأقوال الصحابة", "تُردّ مطلقًا ولا تُحكى", "لا تُقبل إلا إذا تعلقت بالأحكام"], "قسّمها ابن تيمية وتبعه ابن كثير ثلاثة أقسام: ما علمنا صحته مما بأيدينا فيُقبل، وما علمنا كذبه فيُردّ، وما سكت عنه شرعنا فلا نصدّقه ولا نكذّبه وتجوز حكايته، وغالبه لا فائدة فيه تعود إلى أمر ديني."] },

  { id: "ulc-086", s: "ulum", g: 4, d: 5, t: ["tafsir-history", "tafsir-works", "ahkam-al-quran"], tr: ["hanafi", "maliki", "shafii"], src: "al-Jaṣṣāṣ, Aḥkām al-Qurʾān; Ibn al-ʿArabī, Aḥkām al-Qurʾān; Kiyā al-Harrāsī, Aḥkām al-Qurʾān",
    en: ["Three classical works are each titled Aḥkām al-Qurʾān. Which pairing of author and school is correct?", ["al-Jaṣṣāṣ: Ḥanafī; Ibn al-ʿArabī: Mālikī; Kiyā al-Harrāsī: Shāfiʿī", "al-Jaṣṣāṣ: Mālikī; Ibn al-ʿArabī: Shāfiʿī; Kiyā al-Harrāsī: Ḥanafī", "al-Jaṣṣāṣ: Shāfiʿī; Ibn al-ʿArabī: Ḥanafī; Kiyā al-Harrāsī: Mālikī", "al-Jaṣṣāṣ: Ḥanafī; Ibn al-ʿArabī: Shāfiʿī; Kiyā al-Harrāsī: Mālikī"], "Abū Bakr al-Jaṣṣāṣ wrote from the Ḥanafī perspective, Abū Bakr ibn al-ʿArabī (the Mālikī jurist, not the Sufi Ibn ʿArabī) from the Mālikī, and Kiyā al-Harrāsī, a student of al-Juwaynī, from the Shāfiʿī."],
    de: ["Drei klassische Werke tragen jeweils den Titel Aḥkām al-Qurʾān. Welche Zuordnung von Verfasser und Rechtsschule ist richtig?", ["al-Jaṣṣāṣ: ḥanafitisch; Ibn al-ʿArabī: mālikitisch; Kiyā al-Harrāsī: schāfiʿitisch", "al-Jaṣṣāṣ: mālikitisch; Ibn al-ʿArabī: schāfiʿitisch; Kiyā al-Harrāsī: ḥanafitisch", "al-Jaṣṣāṣ: schāfiʿitisch; Ibn al-ʿArabī: ḥanafitisch; Kiyā al-Harrāsī: mālikitisch", "al-Jaṣṣāṣ: ḥanafitisch; Ibn al-ʿArabī: schāfiʿitisch; Kiyā al-Harrāsī: mālikitisch"], "Abū Bakr al-Jaṣṣāṣ schrieb aus ḥanafitischer Sicht, Abū Bakr ibn al-ʿArabī (der mālikitische Jurist, nicht der Sufi Ibn ʿArabī) aus mālikitischer und Kiyā al-Harrāsī, ein Schüler al-Juwaynīs, aus schāfiʿitischer."],
    ar: ["ثلاثة كتب مشهورة بعنوان أحكام القرآن. أيّ نسبة للمؤلفين إلى المذاهب صحيحة؟", ["الجصاص حنفي، وابن العربي مالكي، والكيا الهراسي شافعي", "الجصاص مالكي، وابن العربي شافعي، والكيا الهراسي حنفي", "الجصاص شافعي، وابن العربي حنفي، والكيا الهراسي مالكي", "الجصاص حنفي، وابن العربي شافعي، والكيا الهراسي مالكي"], "كتب أبو بكر الجصاص على مذهب الحنفية، وأبو بكر بن العربي الفقيه المالكي (غير ابن عربي الصوفي) على مذهب المالكية، والكيا الهراسي تلميذ الجويني على مذهب الشافعية."] },

  { id: "ulc-087", s: "ulum", g: 3, d: 4, t: ["tafsir-history", "tafsir-terms"], src: "al-Ṭabarī, Jāmiʿ al-Bayān; Ibn Taymiyya, Muqaddima fī Uṣūl al-Tafsīr; al-Suyūṭī, al-Itqān, ch. on tafsīr and taʾwīl",
    en: ["When al-Ṭabarī introduces a passage with 'the statement on the taʾwīl of His words', in what sense does he use taʾwīl?", ["Explanation of the verse's meaning, the same as tafsīr", "Departing from the apparent meaning because of a proof", "The ultimate reality that only God knows", "Allegorical meanings known only to mystics"], "In the usage of the early mufassirūn, including al-Ṭabarī, taʾwīl means tafsīr, explaining the meaning. The later technical sense, turning a word from its apparent meaning to a less obvious one because of a proof, belongs mainly to the uṣūlīs and theologians."],
    de: ["Wenn al-Ṭabarī einen Abschnitt mit „die Aussage über den taʾwīl Seiner Worte“ einleitet, in welchem Sinn gebraucht er taʾwīl?", ["Erklärung der Bedeutung des Verses, gleichbedeutend mit tafsīr", "Abweichung von der äußeren Bedeutung aufgrund eines Belegs", "Die letzte Wirklichkeit, die nur Gott kennt", "Allegorische Bedeutungen, die nur Mystikern bekannt sind"], "Im Sprachgebrauch der frühen Exegeten, auch al-Ṭabarīs, bedeutet taʾwīl dasselbe wie tafsīr, die Erklärung der Bedeutung. Der spätere Fachsinn, ein Wort aufgrund eines Belegs von der äußeren zu einer weniger naheliegenden Bedeutung zu wenden, gehört vor allem zu den uṣūlī und Theologen."],
    ar: ["حين يقول الطبري: «القول في تأويل قوله تعالى»، فبأيّ معنى يستعمل التأويل؟", ["بمعنى تفسير الكلام وبيان معناه", "بمعنى صرف اللفظ عن ظاهره لدليل", "بمعنى الحقيقة التي لا يعلمها إلا الله", "بمعنى الإشارات الرمزية عند أهل التصوف"], "التأويل في اصطلاح المفسرين المتقدمين ومنهم الطبري بمعنى التفسير وبيان المعنى. أما صرف اللفظ عن ظاهره إلى معنى مرجوح لدليل فاصطلاح متأخر عند الأصوليين والمتكلمين."] },
];
